mapper.select:
/* saleson.shop.statistics.ShopStatisticsMapper.getPaymentStatisticsListByParam */ SELECT TT.PAY_DATE, TT.APPROVAL_TYPE, TT.DEVICE_TYPE, SUM(IF(TT.PAYMENT_TYPE = '1', 1, 0)) AS PAY_COUNT, SUM(IF(TT.PAYMENT_TYPE = '1', TT.AMOUNT, 0)) AS PAY_AMOUNT, SUM(IF(TT.PAYMENT_TYPE = '2', 1, 0)) AS CANCEL_COUNT, SUM(IF(TT.PAYMENT_TYPE = '2', TT.CANCEL_AMOUNT, 0)) AS CANCEL_AMOUNT FROM ( SELECT T.PAY_DATE, T.PAYMENT_TYPE, T.APPROVAL_TYPE, T.DEVICE_TYPE, IF (( SELECT COUNT(*) FROM OP_ORDER_ITEM OI WHERE OI.ORDER_CODE = T.ORDER_CODE AND OI.ORDER_SEQUENCE = T.ORDER_SEQUENCE AND OI.SALES_DATE BETWEEN CONCAT(#{startDate}, '000000') AND CONCAT(#{endDate}, '595959') AND OI.PAY_DATE != '00000000000000' ) > 0, T.AMOUNT, 0) AS AMOUNT, IF (( SELECT COUNT(*) FROM OP_ORDER_ITEM OI WHERE OI.ORDER_CODE = T.ORDER_CODE AND OI.ORDER_SEQUENCE = T.ORDER_SEQUENCE AND OI.CANCEL_FLAG = 'Y' AND OI.SALES_CANCEL_DATE BETWEEN CONCAT(#{startDate}, '000000') AND CONCAT(#{endDate}, '595959') AND OI.PAY_DATE != '00000000000000' ) > 0, T.CANCEL_AMOUNT, 0) AS CANCEL_AMOUNT FROM ( SELECT LEFT(PAY_DATE, 8) AS PAY_DATE, ORDER_CODE, ORDER_SEQUENCE, PAYMENT_TYPE, APPROVAL_TYPE, DEVICE_TYPE, AMOUNT, CANCEL_AMOUNT FROM OP_ORDER_PAYMENT
( (PAYMENT_TYPE = '1' AND IFNULL(PAY_DATE, '') != '') OR (PAYMENT_TYPE = '2' AND CANCEL_AMOUNT > 0) ) AND PAY_DATE BETWEEN CONCAT(#{startDate}, '000000') AND CONCAT(#{endDate}, '595959')
AND APPROVAL_TYPE IN (
#{approvalTypes}
)
) T ) TT GROUP BY TT.PAY_DATE, TT.APPROVAL_TYPE, TT.DEVICE_TYPE

mapper.sql:
SELECT OI.DEVICE_TYPE AS OS_TYPE, OI.ORDER_CODE, OI.ORDER_SEQUENCE, S.SELLER_NAME, OI.USER_ID, O.BUYER_NAME AS USER_NAME, O.MOBILE AS PHONE_NUMBER, '' AS CUSTOMER_CODE, OSI.RECEIVE_SIDO, OSI.RECEIVE_SIGUNGU, OI.SELLER_ID, OI.ITEM_SEQUENCE, OI.ITEM_ID, OI.ITEM_NAME, OI.ITEM_USER_CODE, OI.OPTIONS, OI.BRAND, OI.QUANTITY, OI.SALE_PRICE AS PRICE, OI.COST_PRICE, OI.COMMISSION_BASE_PRICE, OI.COMMISSION_PRICE, IFNULL(OI.CATEGORY_TEAM_ID, 0) AS CATEGORY_TEAM_ID, IFNULL(OI.CATEGORY_GROUP_ID, 0) AS CATEGORY_GROUP_ID, IFNULL(OI.CATEGORY_ID, 0) AS CATEGORY_ID, 'PAY' AS ORDER_TYPE, (OI.PURCHASE_PRICE + OI.OPTION_PRICE) * OI.QUANTITY AS ITEM_PRICE, (OI.SALE_PRICE * OI.QUANTITY) AS TOTAL_ITEM_PRICE, (OI.COUPON_DISCOUNT_PRICE * OI.QUANTITY) AS COUPON_DISCOUNT_AMOUNT, OI.SALES_DATE AS SEARCH_DATE, OSI.RECEIVE_ZIPCODE, OSI.RECEIVE_ADDRESS, OSI.RECEIVE_ADDRESS_DETAIL, OSI.RECEIVE_NAME, O.ZIPCODE, O.ADDRESS, O.ADDRESS_DETAIL, OI.SELLER_DISCOUNT_PRICE, CASE WHEN OI.SPOT_SALE_FLAG = 'Y' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END AS SPOT_DISCOUNT_PRICE, OI.USER_LEVEL_DISCOUNT_PRICE, OI.SET_ITEM_FLAG, OI.SET_DISCOUNT_PRICE FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' INNER JOIN OP_ORDER_SHIPPING_INFO OSI ON OI.ORDER_CODE = OSI.ORDER_CODE AND OI.ORDER_SEQUENCE = OSI.ORDER_SEQUENCE AND OI.SHIPPING_INFO_SEQUENCE = OSI.SHIPPING_INFO_SEQUENCE LEFT JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID
AND OI.USER_ID = #{userId}
AND O.BUYER_NAME = #{userName} AND O.MOBILE = #{mobile}
AND OI.GUEST_FLAG = #{guestFlag}
AND OI.SELLER_ID = #{sellerId}
AND OI.SALES_DATE BETWEEN CONCAT(#{startDate}, '000000') AND CONCAT(#{endDate}, '595959') AND OI.PAY_DATE != '00000000000000'
AND OI.ITEM_NAME LIKE CONCAT('%', #{query}, '%')
AND OSI.RECEIVE_NAME LIKE CONCAT('%', #{query}, '%')
AND ( OI.ITEM_USER_CODE LIKE CONCAT(#{query}, '%') OR OI.OPTIONS LIKE CONCAT('%"optionCode":"', #{query}, '"%') )
AND OI.CATEGORY_ID IN ( SELECT CATEGORY_ID FROM OP_CATEGORY WHERE CATEGORY_CODE LIKE CONCAT(#{categoryClass}, '%') )
AND OI.CATEGORY_TEAM_ID = #{code}
AND OI.CATEGORY_GROUP_ID = #{categoryGroupId}
AND OI.BRAND = #{brand}
AND OI.ITEM_ID = #{itemId}
UNION ALL
SELECT OI.DEVICE_TYPE AS OS_TYPE, OI.ORDER_CODE, OI.ORDER_SEQUENCE, S.SELLER_NAME, OI.USER_ID, O.BUYER_NAME AS USER_NAME, O.MOBILE AS PHONE_NUMBER, '' AS CUSTOMER_CODE, OSI.RECEIVE_SIDO, OSI.RECEIVE_SIGUNGU, OI.SELLER_ID, OI.ITEM_SEQUENCE, OI.ITEM_ID, OI.ITEM_NAME, OI.ITEM_USER_CODE, OI.OPTIONS, OI.BRAND, OI.QUANTITY, OI.SALE_PRICE AS PRICE, OI.COST_PRICE, OI.COMMISSION_BASE_PRICE, OI.COMMISSION_PRICE, IFNULL(OI.CATEGORY_TEAM_ID, 0) AS CATEGORY_TEAM_ID, IFNULL(OI.CATEGORY_GROUP_ID, 0) AS CATEGORY_GROUP_ID, IFNULL(OI.CATEGORY_ID, 0) AS CATEGORY_ID, 'CANCEL' AS ORDER_TYPE, (OI.PURCHASE_PRICE + OI.OPTION_PRICE) * OI.QUANTITY AS ITEM_PRICE, (OI.SALE_PRICE * OI.QUANTITY) AS TOTAL_ITEM_PRICE, (OI.COUPON_DISCOUNT_PRICE * OI.QUANTITY) AS COUPON_DISCOUNT_AMOUNT, OI.SALES_CANCEL_DATE AS SEARCH_DATE, OSI.RECEIVE_ZIPCODE, OSI.RECEIVE_ADDRESS, OSI.RECEIVE_ADDRESS_DETAIL, OSI.RECEIVE_NAME, O.ZIPCODE, O.ADDRESS, O.ADDRESS_DETAIL, OI.SELLER_DISCOUNT_PRICE, CASE WHEN OI.SPOT_SALE_FLAG = 'Y' THEN OI.SPOT_DISCOUNT_PRICE ELSE 0 END AS SPOT_DISCOUNT_PRICE, OI.USER_LEVEL_DISCOUNT_PRICE, OI.SET_ITEM_FLAG, OI.SET_DISCOUNT_PRICE FROM OP_ORDER_ITEM OI INNER JOIN OP_ORDER O ON OI.ORDER_CODE = O.ORDER_CODE AND OI.ORDER_SEQUENCE = O.ORDER_SEQUENCE AND O.DATA_STATUS_CODE = '1' INNER JOIN OP_ORDER_SHIPPING_INFO OSI ON OI.ORDER_CODE = OSI.ORDER_CODE AND OI.ORDER_SEQUENCE = OSI.ORDER_SEQUENCE AND OI.SHIPPING_INFO_SEQUENCE = OSI.SHIPPING_INFO_SEQUENCE LEFT JOIN OP_SELLER S ON OI.SELLER_ID = S.SELLER_ID
OI.CANCEL_FLAG = 'Y'
AND OI.USER_ID = #{userId}
AND O.BUYER_NAME = #{userName} AND O.MOBILE = #{mobile}
AND OI.GUEST_FLAG = #{guestFlag}
AND OI.SELLER_ID = #{sellerId}
AND OI.SALES_CANCEL_DATE BETWEEN CONCAT(#{startDate}, '000000') AND CONCAT(#{endDate}, '595959') AND OI.PAY_DATE != '00000000000000'
AND OI.ITEM_NAME LIKE CONCAT('%', #{query}, '%')
AND OSI.RECEIVE_NAME LIKE CONCAT('%', #{query}, '%')
AND ( OI.ITEM_USER_CODE LIKE CONCAT(#{query}, '%') OR OI.OPTIONS LIKE CONCAT('%"optionCode":"', #{query}, '"%') )
AND OI.CATEGORY_ID IN ( SELECT CATEGORY_ID FROM OP_CATEGORY WHERE CATEGORY_CODE LIKE CONCAT(#{categoryClass}, '%') )
AND OI.CATEGORY_TEAM_ID = #{code}
AND OI.CATEGORY_GROUP_ID = #{categoryGroupId}
AND OI.BRAND = #{brand}
AND OI.ITEM_ID = #{itemId}

SELECT TT.BRAND, ( SELECT SUM(PAY_TOTAL - CANCEL_TOTAL) AS TOTAL_BUY_AMOUNT FROM ( SELECT A.BRAND, SUM( CASE WHEN A.ORDER_TYPE = 'PAY' THEN A.TOTAL_ITEM_PRICE ELSE 0 END ) AS PAY_TOTAL, SUM( CASE WHEN A.ORDER_TYPE = 'CANCEL' THEN A.TOTAL_ITEM_PRICE ELSE 0 END ) AS CANCEL_TOTAL FROM (
) A GROUP BY A.BRAND, A.ORDER_TYPE ) T WHERE T.BRAND = TT.BRAND GROUP BY T.BRAND ) AS TOTAL_BUY_AMOUNT, ( SELECT SUM(PAY_TOTAL - CANCEL_TOTAL) AS TOTAL_BUY_QUANTITY FROM ( SELECT A.BRAND, SUM( CASE WHEN A.ORDER_TYPE = 'PAY' THEN A.QUANTITY ELSE 0 END ) AS PAY_TOTAL, SUM( CASE WHEN A.ORDER_TYPE = 'CANCEL' THEN A.QUANTITY ELSE 0 END ) AS CANCEL_TOTAL FROM (
) A GROUP BY A.BRAND, A.ORDER_TYPE ) T WHERE T.BRAND = TT.BRAND GROUP BY T.BRAND ) AS TOTAL_BUY_QUANTITY,
FROM ( SELECT IFNULL(OI.BRAND, '') AS BRAND, OI.ORDER_TYPE, SUM(OI.ITEM_PRICE) AS SUM_ITEM_PRICE, SUM(OI.COUPON_DISCOUNT_AMOUNT) AS SUM_ITEM_COUPON_DISCOUNT_AMOUNT, SUM(OI.COUNT) AS `COUNT`, (CASE WHEN OI.OS_TYPE = '11st' OR OI.OS_TYPE = 'gmarket' OR OI.OS_TYPE = 'auction' OR OI.OS_TYPE = 'storefarm' OR OI.OS_TYPE = 'naver' THEN '오픈마켓' WHEN OI.OS_TYPE = 'allthat' OR OI.OS_TYPE = 'beautycall' THEN 'Resale' WHEN OI.OS_TYPE = 'Admin' THEN 'Call' ELSE OI.OS_TYPE END ) AS OS_TYPE FROM ( SELECT T.OS_TYPE, T.ORDER_CODE, T.BRAND, T.ORDER_TYPE, SUM(T.QUANTITY) AS `COUNT`, SUM(T.TOTAL_ITEM_PRICE) AS ITEM_PRICE, SUM(IFNULL(T.COUPON_DISCOUNT_AMOUNT, 0)) AS COUPON_DISCOUNT_AMOUNT FROM (
) T GROUP BY T.ORDER_CODE, T.BRAND, T.ORDER_TYPE, T.OS_TYPE ) OI GROUP BY OI.ORDER_TYPE, OI.BRAND, OI.OS_TYPE ) TT GROUP BY TT.BRAND, TT.OS_TYPE

SELECT U.USER_ID, TT.CUSTOMER_CODE, '' AS CUSTOMER_TEL_NUMBER, U.USER_NAME AS USERNAME, U.LOGIN_ID, U.EMAIL, ( SELECT SUM(PAY_TOTAL - CANCEL_TOTAL) AS TOTAL_BUY_AMOUNT FROM ( SELECT A.CUSTOMER_CODE, SUM( CASE WHEN A.ORDER_TYPE = 'PAY' THEN A.TOTAL_ITEM_PRICE ELSE 0 END ) AS PAY_TOTAL, SUM( CASE WHEN A.ORDER_TYPE = 'CANCEL' THEN A.TOTAL_ITEM_PRICE ELSE 0 END ) AS CANCEL_TOTAL FROM (
) A GROUP BY A.CUSTOMER_CODE, A.ORDER_TYPE ) T WHERE T.CUSTOMER_CODE = TT.CUSTOMER_CODE GROUP BY T.CUSTOMER_CODE ) AS TOTAL_BUY_AMOUNT, ( SELECT SUM(PAY_TOTAL - CANCEL_TOTAL) AS TOTAL_BUY_QUANTITY FROM ( SELECT A.CUSTOMER_CODE, SUM( CASE WHEN A.ORDER_TYPE = 'PAY' THEN A.QUANTITY ELSE 0 END ) AS PAY_TOTAL, SUM( CASE WHEN A.ORDER_TYPE = 'CANCEL' THEN A.QUANTITY ELSE 0 END ) AS CANCEL_TOTAL FROM (
) A GROUP BY A.CUSTOMER_CODE, A.ORDER_TYPE ) T WHERE T.CUSTOMER_CODE = TT.CUSTOMER_CODE GROUP BY T.CUSTOMER_CODE ) AS TOTAL_BUY_QUANTITY,
FROM (
SELECT OI.USER_ID, OI.CUSTOMER_CODE, OI.ORDER_TYPE, (CASE WHEN OI.OS_TYPE = '11st' OR OI.OS_TYPE = 'gmarket' OR OI.OS_TYPE = 'auction' OR OI.OS_TYPE = 'storefarm' OR OI.OS_TYPE = 'naver' THEN '오픈마켓' WHEN OI.OS_TYPE = 'allthat' OR OI.OS_TYPE = 'beautycall' THEN 'Resale' WHEN OI.OS_TYPE = 'Admin' THEN 'Call' ELSE OI.OS_TYPE END ) AS OS_TYPE, COUNT(*) AS `COUNT`, SUM(OI.ITEM_PRICE) AS SUM_ITEM_PRICE, 0 AS SUM_USE_POINT, 0 AS SUM_DELIVERY_PRICE, 0 AS SUM_DISCOUNT_AMOUNT, SUM(OI.COST_PRICE) AS SUM_COST_PRICE FROM ( SELECT T.OS_TYPE, T.USER_ID, T.USER_ID AS CUSTOMER_CODE, T.ORDER_CODE, T.ORDER_TYPE, SUM(T.TOTAL_ITEM_PRICE) AS ITEM_PRICE, SUM(T.COST_PRICE * T.QUANTITY) AS COST_PRICE, SUM(T.PAY_SHIPPING) AS PAY_SHIPPING FROM (
) T GROUP BY T.ORDER_CODE, T.ORDER_TYPE, T.OS_TYPE ) OI
AND OI.USER_ID IN ( SELECT USER_ID FROM OP_USER WHERE STATUS_CODE = 9 AND USERNAME LIKE CONCAT(#{query}, '%') )
AND OI.USER_ID IN ( SELECT USER_ID FROM OP_USER WHERE STATUS_CODE = 9 AND ( LOGIN_ID LIKE CONCAT(#{query}, '%') OR EMAIL LIKE CONCAT(#{query}, '%') ) )
GROUP BY OI.ORDER_TYPE, OI.CUSTOMER_CODE, OI.OS_TYPE ) TT LEFT JOIN OP_USER U ON C.USER_ID = U.USER_ID GROUP BY TT.CUSTOMER_CODE, TT.OS_TYPE

SELECT C.CATEGORY_TEAM_ID, C.TEAM_CODE, C.TEAM_NAME, C.CATEGORY_GROUP_ID , C.GROUP_CODE, C.GROUP_NAME, C.CATEGORY_NAME, C.CATEGORY_ID, C.CATEGORY_URL, C.CATEGORY_CODE, C.CATEGORY_CLASS1, C.CATEGORY_CLASS2, C.CATEGORY_CLASS3, C.CATEGORY_CLASS4, C.CATEGORY_LEVEL, IC.ITEM_ID, I.DISPLAY_FLAG, I.ITEM_NAME, I.ITEM_IMAGE, I.ITEM_USER_CODE, I.PAY_COUNT, I.TOTAL_ITEM_PRICE FROM ( SELECT CT.CATEGORY_TEAM_ID, CT.CODE AS TEAM_CODE, CT.NAME AS TEAM_NAME, CG.CATEGORY_GROUP_ID , CG.CODE AS GROUP_CODE, CG.NAME AS GROUP_NAME, C2.CATEGORY_NAME, C2.CATEGORY_ID , C2.CATEGORY_URL , C2.CATEGORY_CODE , C2.CATEGORY_CLASS1 , C2.CATEGORY_CLASS2 , C2.CATEGORY_CLASS3 , C2.CATEGORY_CLASS4 , C2.CATEGORY_LEVEL FROM OP_CATEGORY_TEAM AS CT LEFT JOIN OP_CATEGORY_GROUP AS CG ON CT.CATEGORY_TEAM_ID = CG.CATEGORY_TEAM_ID AND CG.CATEGORY_GROUP_FLAG = 'Y' RIGHT JOIN OP_CATEGORY AS C ON CG.CATEGORY_GROUP_ID = C.CATEGORY_GROUP_ID AND C.CATEGORY_FLAG = 'Y' RIGHT JOIN OP_CATEGORY AS C2 ON C.CATEGORY_CLASS1 = C2.CATEGORY_CLASS1 AND C2.CATEGORY_FLAG = 'Y' WHERE CT.CATEGORY_TEAM_FLAG = 'Y'
AND C2.CATEGORY_CODE LIKE CONCAT(#{categoryClass}, '%')
AND CT.CATEGORY_TEAM_ID = #{code}
AND CG.CATEGORY_GROUP_ID = #{categoryGroupId}
) C INNER JOIN OP_ITEM_CATEGORY AS IC ON C.CATEGORY_ID = IC.CATEGORY_ID INNER JOIN ( SELECT I.ITEM_ID, I.ITEM_NAME, I.ITEM_IMAGE, I.ITEM_USER_CODE, I.DISPLAY_FLAG, COUNT(OI.PAY_DATE) AS PAY_COUNT, IFNULL(SUM(OI.TOTAL_ITEM_PRICE),0) AS TOTAL_ITEM_PRICE FROM OP_ITEM I LEFT JOIN ( SELECT * FROM OP_ORDER_ITEM WHERE (CANCEL_DATE IS NOT NULL AND CANCEL_DATE != '') AND PAY_DATE BETWEEN CONCAT(#{startDate}, '000000') AND CONCAT(#{endDate}, '595959') ) OI ON I.ITEM_ID = OI.ITEM_ID GROUP BY I.ITEM_ID, I.ITEM_NAME, I.ITEM_IMAGE, I.ITEM_USER_CODE, I.DISPLAY_FLAG ) I ON IC.ITEM_ID = I.ITEM_ID
AND I.ITEM_NAME LIKE CONCAT('%', #{itemName}, '%')
AND I.PAY_COUNT <= #{salesCount}
AND I.TOTAL_ITEM_PRICE <= #{salesPrice}

mapper.select:
/* saleson.shop.statistics.ShopStatisticsMapper.getShopItemDetailList */ SELECT TT.USER_ID, TT.USER_NAME, TT.LOGIN_ID, TT.PHONE_NUMBER, TT.ZIPCODE, TT.ADDRESS, TT.ADDRESS_DETAIL, TT.CUSTOMER_CODE, SUM(TT.QUANTITY) AS QUANTITY, SUM(TT.TOTAL_ITEM_PRICE) AS ITEM_PRICE, TT.ORDER_TYPE FROM ( SELECT T.USER_ID, IFNULL(T.USER_NAME, '비회원') AS USER_NAME, T.PHONE_NUMBER, T.CUSTOMER_CODE, T.ITEM_ID, T.QUANTITY, T.ORDER_TYPE, T.TOTAL_ITEM_PRICE, T.ZIPCODE, T.ADDRESS, T.ADDRESS_DETAIL, U.LOGIN_ID
FROM (
) AS T LEFT JOIN OP_USER AS U ON T.USER_ID = U.USER_ID
WHERE T.ITEM_ID = #{itemId} ) TT GROUP BY TT.USER_ID, TT.ORDER_TYPE, TT.USER_NAME, TT.LOGIN_ID ORDER BY TT.TOTAL_ITEM_PRICE DESC

/* saleson.shop.statistics.ShopStatisticsMapper.getUserStatisticsCountByParam */
SELECT COUNT(*) AS `COUNT` FROM (

) T

/* saleson.shop.statistics.ShopStatisticsMapper.getDoNotSellItemCountByParam */
SELECT COUNT(*) AS `COUNT` FROM
(

) T

/* saleson.shop.statistics.ShopStatisticsMapper.getShippingDetailListForDateByParam */ SELECT O.SEARCH_DATE AS `DATE`, O.ORDER_CODE, O.PAY_TYPE AS ORDER_TYPE, O.ITEM_AMOUNT, O.SHIPPING - O.ITEM_AMOUNT AS SUM_DELIVERY_PRICE, O.CART_COUPON_DISCOUNT_AMOUNT, O.ITEM_PRICE, O.COUPON_DISCOUNT, O.SPOT_DISCOUNT, O.SELLER_DISCOUNT, O.USER_LEVEL_DISCOUNT, O.SET_DISCOUNT FROM ( SELECT 'PAY' AS PAY_TYPE, SEARCH_DATE, ORDER_CODE, SUM(ITEM_PRICE) AS ITEM_PRICE, SUM(COUPON_DISCOUNT) AS COUPON_DISCOUNT, SUM(SPOT_DISCOUNT) AS SPOT_DISCOUNT, SUM(SELLER_DISCOUNT) AS SELLER_DISCOUNT, SUM(USER_LEVEL_DISCOUNT) AS USER_LEVEL_DISCOUNT, SUM(SET_DISCOUNT) AS SET_DISCOUNT, SUM(SALE_PRICE) AS ITEM_AMOUNT, ( SELECT CASE WHEN ( SELECT COUNT(*) FROM OP_ORDER_PAYMENT WHERE ORDER_CODE = T.ORDER_CODE AND PAYMENT_TYPE = '1' AND PAY_DATE LIKE CONCAT(T.SEARCH_DATE, '%') ) > 0 THEN IFNULL(( SELECT SUM(AMOUNT) FROM OP_ORDER_PAYMENT WHERE ORDER_CODE = T.ORDER_CODE AND PAYMENT_TYPE = '1' AND ( APPROVAL_TYPE = 'walfare' OR APPROVAL_TYPE = 'giftcard' OR APPROVAL_TYPE = 'point' OR (APPROVAL_TYPE != 'walfare' AND APPROVAL_TYPE != 'giftcard' AND APPROVAL_TYPE != 'point' AND PAY_DATE LIKE CONCAT(T.SEARCH_DATE, '%') ) ) GROUP BY ORDER_CODE ), 0) ELSE IFNULL(( SELECT SUM(AMOUNT) FROM OP_ORDER_PAYMENT WHERE ORDER_CODE = T.ORDER_CODE AND PAYMENT_TYPE = '1' AND PAY_DATE LIKE CONCAT(T.SEARCH_DATE, '%') GROUP BY ORDER_CODE) , 0) END AS P ) AS SHIPPING, IFNULL(( SELECT SUM(DISCOUNT_SHIPPING) FROM OP_ORDER_SHIPPING WHERE ORDER_CODE = T.ORDER_CODE AND SHIPPING_PAYMENT_TYPE = '1' GROUP BY ORDER_CODE ), 0) AS CART_COUPON_DISCOUNT_AMOUNT FROM ( SELECT LEFT(OI.SALES_DATE, 8) AS SEARCH_DATE, OI.ORDER_CODE, (OI.PURCHASE_PRICE + OI.OPTION_PRICE) * OI.QUANTITY AS ITEM_PRICE, OI.COUPON_DISCOUNT_PRICE * OI.QUANTITY AS COUPON_DISCOUNT, CASE WHEN OI.SPOT_SALE_FLAG = 'Y' THEN OI.SPOT_DISCOUNT_PRICE * OI.QUANTITY ELSE 0 END AS SPOT_DISCOUNT, OI.SELLER_DISCOUNT_PRICE * OI.QUANTITY AS SELLER_DISCOUNT, OI.USER_LEVEL_DISCOUNT_PRICE * OI.QUANTITY AS USER_LEVEL_DISCOUNT, OI.SET_DISCOUNT_PRICE * OI.QUANTITY AS SET_DISCOUNT, OI.SALE_PRICE * OI.QUANTITY AS SALE_PRICE FROM OP_ORDER_ITEM OI
AND OI.USER_ID = #{userId}
AND OI.GUEST_FLAG = #{guestFlag}
AND OI.SELLER_ID = #{sellerId}
AND OI.SALES_DATE BETWEEN CONCAT(#{startDate}, '000000') AND CONCAT(#{endDate}, '595959') AND OI.PAY_DATE != '00000000000000'
AND OI.ITEM_NAME LIKE CONCAT('%', #{query}, '%')
AND ( OI.ITEM_USER_CODE LIKE CONCAT(#{query}, '%') OR OI.OPTIONS LIKE CONCAT('%"optionCode":"', #{query}, '"%') )
AND OI.CATEGORY_ID IN ( SELECT CATEGORY_ID FROM OP_CATEGORY WHERE CATEGORY_CODE LIKE CONCAT(#{categoryClass}, '%') )
AND OI.CATEGORY_TEAM_ID = #{code}
AND OI.CATEGORY_GROUP_ID = #{categoryGroupId}
AND OI.BRAND = #{brand}
AND OI.ITEM_ID = #{itemId}
) T GROUP BY SEARCH_DATE, ORDER_CODE
UNION ALL
SELECT 'CANCEL' AS PAY_TYPE, SEARCH_DATE, ORDER_CODE, SUM(ITEM_PRICE) AS ITEM_PRICE, SUM(COUPON_DISCOUNT) AS COUPON_DISCOUNT, SUM(SPOT_DISCOUNT) AS SPOT_DISCOUNT, SUM(SELLER_DISCOUNT) AS SELLER_DISCOUNT, SUM(USER_LEVEL_DISCOUNT) AS USER_LEVEL_DISCOUNT, SUM(SET_DISCOUNT) AS SET_DISCOUNT, SUM(SALE_PRICE) AS ITEM_AMOUNT, IFNULL(( SELECT SUM(CANCEL_AMOUNT) FROM OP_ORDER_PAYMENT WHERE ORDER_CODE = T.ORDER_CODE AND PAYMENT_TYPE = '2' AND PAY_DATE LIKE CONCAT(T.SEARCH_DATE, '%') GROUP BY ORDER_CODE ), 0) AS SHIPPING, IFNULL(( SELECT SUM(DISCOUNT_SHIPPING) FROM OP_ORDER_SHIPPING WHERE ORDER_CODE = T.ORDER_CODE AND SHIPPING_PAYMENT_TYPE = '1' GROUP BY ORDER_CODE ), 0) AS CART_COUPON_DISCOUNT_AMOUNT FROM ( SELECT LEFT(OI.SALES_CANCEL_DATE, 8) AS SEARCH_DATE, OI.ORDER_CODE, (OI.PURCHASE_PRICE + OI.OPTION_PRICE) * OI.QUANTITY AS ITEM_PRICE, OI.COUPON_DISCOUNT_PRICE * OI.QUANTITY AS COUPON_DISCOUNT, CASE WHEN OI.SPOT_SALE_FLAG = 'Y' THEN OI.SPOT_DISCOUNT_PRICE * OI.QUANTITY ELSE 0 END AS SPOT_DISCOUNT, OI.SELLER_DISCOUNT_PRICE * OI.QUANTITY AS SELLER_DISCOUNT, OI.USER_LEVEL_DISCOUNT_PRICE * OI.QUANTITY AS USER_LEVEL_DISCOUNT, OI.SET_DISCOUNT_PRICE * OI.QUANTITY AS SET_DISCOUNT, OI.SALE_PRICE * OI.QUANTITY AS SALE_PRICE FROM OP_ORDER_ITEM OI
AND OI.USER_ID = #{userId}
AND OI.GUEST_FLAG = #{guestFlag}
AND OI.SELLER_ID = #{sellerId}
AND OI.SALES_CANCEL_DATE BETWEEN CONCAT(#{startDate}, '000000') AND CONCAT(#{endDate}, '595959') AND OI.PAY_DATE != '00000000000000'
AND OI.ITEM_NAME LIKE CONCAT('%', #{query}, '%')
AND ( OI.ITEM_USER_CODE LIKE CONCAT(#{query}, '%') OR OI.OPTIONS LIKE CONCAT('%"optionCode":"', #{query}, '"%') )
AND OI.CATEGORY_ID IN ( SELECT CATEGORY_ID FROM OP_CATEGORY WHERE CATEGORY_CODE LIKE CONCAT(#{categoryClass}, '%') )
AND OI.CATEGORY_TEAM_ID = #{code}
AND OI.CATEGORY_GROUP_ID = #{categoryGroupId}
AND OI.BRAND = #{brand}
AND OI.ITEM_ID = #{itemId}
) T GROUP BY SEARCH_DATE, ORDER_CODE ) O ORDER BY O.ORDER_CODE DESC, O.PAY_TYPE DESC

/* saleson.shop.statistics.ShopStatisticsMapper.getOrderListByParam */ SELECT O2.ORDER_ID , O2.ORDER_CODE , O2.ORDER_COUNT , O2.USERNAME , O2.LOGIN_ID, ITEM_EXCISE_PRICE , COUPON_DISCOUNT_AMOUNT , CART_COUPON_DISCOUNT_AMOUNT , SUM_USE_POINT , VENDOR_ADD_DISCOUNT_AMOUNT , SUM_DELIVERY_PRICE , VENDOR_ADD_DELIVERY_EXTRA_CHARGE , ORDER_STATUS, ORDER_TYPE , OS_TYPE , SEARCH_DATE, OI2.ORDER_ITEM_ID, OI2.QUANTITY, OI2.ITEMS_EXCISE_PRICE, OI2.ITEM_NAME , OI2.ITEM_USER_CODE, OI2.ITEM_IMAGE FROM ( SELECT O.ORDER_ID , O.ORDER_CODE , U.USER_NAME , U.LOGIN_ID, ORDER_COUNT , ITEM_EXCISE_PRICE, COUPON_DISCOUNT_AMOUNT, CART_COUPON_DISCOUNT_AMOUNT, SUM_USE_POINT, IFNULL(OP.ADD_DISCOUNT_AMOUNT,0) AS VENDOR_ADD_DISCOUNT_AMOUNT, SUM_DELIVERY_PRICE, IFNULL(OP.ADD_DELIVERY_PRICE,0) AS VENDOR_ADD_DELIVERY_EXTRA_CHARGE,
CASE WHEN OI.ORDER_STATUS IN ('1', '2', '3', '8', '9') THEN '결제' WHEN OI.ORDER_STATUS IN ('10', '16', '99') THEN '취소' END AS ORDER_STATUS ,
CASE WHEN OI.ORDER_STATUS IN ('1', '2', '3', '8', '9') THEN '1' WHEN OI.ORDER_STATUS IN ('10', '16', '99') THEN '2' END AS ORDER_TYPE,
OS_TYPE , SEARCH_DATE FROM ( SELECT ORDER_ID, COUNT(ORDER_ID) AS ORDER_COUNT , ORDER_STATUS, SUM(ITEM_EXCISE_PRICE) AS ITEM_EXCISE_PRICE, SUM(COUPON_DISCOUNT_AMOUNT) AS COUPON_DISCOUNT_AMOUNT, SEARCH_DATE FROM (
SELECT ORDER_ID, ORDER_STATUS , (TOTAL_ITEM_PRICE + EXCISE_PRICE) AS ITEM_EXCISE_PRICE , COUPON_DISCOUNT_AMOUNT , CASE WHEN CANCEL_DATE <> '' AND CANCEL_DATE IS NOT NULL THEN CANCEL_DATE ELSE PAY_DATE END AS SEARCH_DATE
FROM OP_ORDER_ITEM WHERE (PAY_DATE <> '' OR PAY_DATE IS NULL)
) AS OI2 GROUP BY ORDER_ID, SEARCH_DATE ) AS OI LEFT JOIN OP_ORDER AS O ON O.ORDER_ID = OI.ORDER_ID LEFT JOIN OP_ORDER_PAYMENT AS OP ON O.ORDER_PAYMENT_ID = OP.ORDER_PAYMENT_ID LEFT JOIN OP_USER AS U ON U.USER_ID = O.USER_ID WHERE SEARCH_DATE LIKE CONCAT(#{searchDate},'%') ) AS O2 LEFT JOIN (
SELECT OI.ORDER_ITEM_ID, OI.ORDER_ID , OI.QUANTITY , (OI.TOTAL_ITEM_PRICE + OI.EXCISE_PRICE) AS ITEMS_EXCISE_PRICE , I.* FROM OP_ORDER_ITEM AS OI LEFT JOIN OP_ITEM AS I ON OI.ITEM_ID = I.ITEM_ID WHERE ( PAY_DATE LIKE CONCAT(#{searchDate},'%') OR CANCEL_DATE LIKE CONCAT(#{searchDate},'%') ) AND (PAY_DATE <> '' OR PAY_DATE IS NULL)
) AS OI2 ON O2.ORDER_ID = OI2.ORDER_ID

/* saleson.shop.statistics.ShopStatisticsMapper.getAreaDetailList */ SELECT USER_ID, USER_NAME, LOGIN_ID, TT.ZIPCODE, TT.ADDRESS, TT.ADDRESS_DETAIL, CUSTOMER_CODE, SUM(QUANTITY) AS QUANTITY, SUM(ITEM_PRICE) - SUM(TT.COUPON_DISCOUNT_AMOUNT) - SUM(TT.SELLER_DISCOUNT_AMOUNT) - SUM(TT.SPOT_DISCOUNT_AMOUNT) - SUM(TT.USER_LEVEL_DISCOUNT_AMOUNT) - SUM(TT.SET_DISCOUNT_AMOUNT) AS ITEM_PRICE, ORDER_TYPE FROM ( SELECT T.USER_ID, IFNULL(T.USER_NAME, '비회원') AS USER_NAME, T.CUSTOMER_CODE, T.RECEIVE_SIDO, T.RECEIVE_SIGUNGU, T.QUANTITY, T.ORDER_TYPE, T.ITEM_PRICE, T.TOTAL_ITEM_PRICE, T.COUPON_DISCOUNT_AMOUNT, T.ZIPCODE, T.ADDRESS, T.ADDRESS_DETAIL, T.SELLER_DISCOUNT_PRICE * T.QUANTITY AS SELLER_DISCOUNT_AMOUNT, T.SPOT_DISCOUNT_PRICE * T.QUANTITY AS SPOT_DISCOUNT_AMOUNT, T.USER_LEVEL_DISCOUNT_PRICE * T.QUANTITY AS USER_LEVEL_DISCOUNT_AMOUNT, T.SET_DISCOUNT_PRICE * T.QUANTITY AS SET_DISCOUNT_AMOUNT, U.LOGIN_ID FROM (
) AS T LEFT JOIN OP_USER AS U ON T.USER_ID = U.USER_ID LEFT JOIN OP_SIDO_MAPPING SM ON T.RECEIVE_SIDO = SM.SIDO_DATA WHERE
(T.RECEIVE_SIGUNGU = #{dodobuhyun} OR T.RECEIVE_SIGUNGU IS NULL)
T.RECEIVE_SIGUNGU = #{dodobuhyun}
AND SM.SIDO_MAPPING_GROUP_KEY IS NULL
AND SM.SIDO_MAPPING_GROUP_KEY = #{sidoMappingGroupKey}
) AS TT GROUP BY TT.USER_ID, TT.ORDER_TYPE ORDER BY TOTAL_ITEM_PRICE DESC

/* saleson.shop.statistics.ShopStatisticsMapper.getUserOrderItemListByParam */ SELECT OI2.ORDER_ITEM_ID, OI2.QUANTITY, OI2.ITEMS_EXCISE_PRICE, OI2.ITEM_NAME , OI2.ITEM_USER_CODE, OI2.ITEM_IMAGE FROM (
SELECT OI.ORDER_ITEM_ID, OI.ORDER_ID , OI.QUANTITY , (OI.TOTAL_ITEM_PRICE + OI.EXCISE_PRICE) AS ITEMS_EXCISE_PRICE , I.* FROM OP_ORDER_ITEM AS OI LEFT JOIN OP_ITEM AS I ON OI.ITEM_ID = I.ITEM_ID WHERE ( PAY_DATE BETWEEN CONCAT(#{startDate},'000000') AND CONCAT(#{endDate},'595959') OR CANCEL_DATE BETWEEN CONCAT(#{startDate},'000000') AND CONCAT(#{endDate},'595959') ) AND (PAY_DATE <> '' OR PAY_DATE IS NULL)
) AS OI2 WHERE OI2.ORDER_ID = #{orderId}

/* saleson.shop.statistics.ShopStatisticsMapper.getUserOrderListByParam */ SELECT O2.ORDER_ID , O2.ORDER_CODE , O2.ORDER_COUNT , O2.USERNAME , O2.LOGIN_ID, ITEM_EXCISE_PRICE , COUPON_DISCOUNT_AMOUNT , CART_COUPON_DISCOUNT_AMOUNT , SUM_USE_POINT , VENDOR_ADD_DISCOUNT_AMOUNT , SUM_DELIVERY_PRICE , VENDOR_ADD_DELIVERY_EXTRA_CHARGE , ORDER_STATUS, ORDER_TYPE , OS_TYPE , SEARCH_DATE, OI2.ORDER_ITEM_ID, OI2.QUANTITY, OI2.ITEMS_EXCISE_PRICE, OI2.ITEM_NAME , OI2.ITEM_USER_CODE, OI2.ITEM_IMAGE FROM ( SELECT O.ORDER_ID, O.ORDER_CODE, U.USER_NAME, U.LOGIN_ID, U.USER_ID, ORDER_COUNT, ITEM_EXCISE_PRICE, COUPON_DISCOUNT_AMOUNT, CART_COUPON_DISCOUNT_AMOUNT, SUM_USE_POINT, IFNULL(OP.ADD_DISCOUNT_AMOUNT,0) AS VENDOR_ADD_DISCOUNT_AMOUNT, SUM_DELIVERY_PRICE, IFNULL(OP.ADD_DELIVERY_PRICE,0) AS VENDOR_ADD_DELIVERY_EXTRA_CHARGE,
CASE WHEN OI.ORDER_STATUS IN ('1', '2', '3', '8', '9') THEN '결제' WHEN OI.ORDER_STATUS IN ('10', '16', '99') THEN '취소' END AS ORDER_STATUS ,
CASE WHEN OI.ORDER_STATUS IN ('1', '2', '3', '8', '9') THEN '1' WHEN OI.ORDER_STATUS IN ('10', '16', '99') THEN '2' END AS ORDER_TYPE,
OS_TYPE , SEARCH_DATE FROM ( SELECT ORDER_ID, COUNT(ORDER_ID) AS ORDER_COUNT , ORDER_STATUS, SUM(ITEM_EXCISE_PRICE) AS ITEM_EXCISE_PRICE, SUM(COUPON_DISCOUNT_AMOUNT) AS COUPON_DISCOUNT_AMOUNT, SEARCH_DATE FROM (
SELECT ORDER_ID, ORDER_STATUS , (TOTAL_ITEM_PRICE + EXCISE_PRICE) AS ITEM_EXCISE_PRICE , COUPON_DISCOUNT_AMOUNT , CASE WHEN CANCEL_DATE <> '' AND CANCEL_DATE IS NOT NULL THEN CANCEL_DATE ELSE PAY_DATE END AS SEARCH_DATE
FROM OP_ORDER_ITEM WHERE (PAY_DATE <> '' OR PAY_DATE IS NULL)
) AS OI2 GROUP BY ORDER_ID, SEARCH_DATE ) AS OI LEFT JOIN OP_ORDER AS O ON O.ORDER_ID = OI.ORDER_ID LEFT JOIN OP_ORDER_PAYMENT AS OP ON O.ORDER_PAYMENT_ID = OP.ORDER_PAYMENT_ID LEFT JOIN OP_USER AS U ON U.USER_ID = O.USER_ID WHERE SEARCH_DATE BETWEEN CONCAT(#{startDate},'000000') AND CONCAT(#{endDate},'595959') ) AS O2 LEFT JOIN (
SELECT OI.ORDER_ITEM_ID, OI.ORDER_ID , OI.QUANTITY , (OI.TOTAL_ITEM_PRICE + OI.EXCISE_PRICE) AS ITEMS_EXCISE_PRICE , I.* FROM OP_ORDER_ITEM AS OI LEFT JOIN OP_ITEM AS I ON OI.ITEM_ID = I.ITEM_ID WHERE ( PAY_DATE BETWEEN CONCAT(#{startDate},'000000') AND CONCAT(#{endDate},'595959') OR CANCEL_DATE BETWEEN CONCAT(#{startDate},'000000') AND CONCAT(#{endDate},'595959') ) AND (PAY_DATE <> '' OR PAY_DATE IS NULL)
) AS OI2 ON O2.ORDER_ID = OI2.ORDER_ID WHERE O2.USER_ID = #{userId}

/* saleson.shop.statistics.ShopStatisticsMapper.getNotUserList */
SELECT U.*, POST , ADDRESS , ADDRESS_DETAIL , TEL_NUMBER , PHONE_NUMBER , FAX_NUMBER , RECEIVE_EMAIL , RECEIVE_SMS , GENDER , POINT , BUY_COUNT , BUY_PRICE , LAST_BUY_DATE , LEAVE_REASON , SITE_FLAG , LEVEL , USE_FLAG , IFNULL(O.PAY_COUNT,0) AS PAY_COUNT, IFNULL(O.TOTAL_ITEM_PRICE,0) TOTAL_ITEM_PRICE FROM OP_USER AS U LEFT JOIN OP_USER_DETAIL AS UD ON U.USER_ID = UD.USER_ID LEFT JOIN OP_USER_ROLE AS UR ON U.USER_ID = UR.USER_ID LEFT JOIN ( SELECT O.USER_ID, COUNT(OI.PAY_DATE) AS PAY_COUNT, IFNULL(SUM(OI.TOTAL_ITEM_PRICE),0) AS TOTAL_ITEM_PRICE FROM OP_ORDER AS O ,OP_ORDER_ITEM AS OI WHERE O.ORDER_ID = OI.ORDER_ID AND (OI.CANCEL_DATE IS NOT NULL AND OI.CANCEL_DATE != '') AND OI.PAY_DATE BETWEEN CONCAT(#{startDate},'000000') AND CONCAT(#{endDate},'595959') GROUP BY O.USER_ID ) AS O ON U.USER_ID = O.USER_ID WHERE AUTHORITY LIKE CONCAT('ROLE_USER','%') AND U.STATUS_CODE = '9'
AND IFNULL(O.PAY_COUNT,0) <= #{salesCount}
AND IFNULL(O.TOTAL_ITEM_PRICE,0) <= #{salesPrice}
ORDER BY USER_ID ASC

