/* saleson.shop.statistics.ShopStatisticsMapper.getDateStatsList */ SELECT T.SEARCH_DATE, T.DEVICE_TYPE, SUM(CAST(T.SALE_COUNT AS BIGINT)) AS SALE_COUNT, SUM(CAST(T.SALE_AMOUNT AS BIGINT)) AS SALE_AMOUNT, SUM(CAST(T.CANCEL_AMOUNT AS BIGINT)) AS CANCEL_AMOUNT, SUM(CAST(T.CANCEL_COUNT AS BIGINT)) AS CANCEL_COUNT, SUM(CAST(T.ITEM_PRICE AS BIGINT)) AS ITEM_PRICE, SUM(CAST(T.CANCEL_ITEM_PRICE AS BIGINT)) AS CANCEL_ITEM_PRICE, SUM(CAST(T.COUPON_DISCOUNT_PRICE AS BIGINT)) AS COUPON_DISCOUNT_PRICE, SUM(CAST(T.SELLER_DISCOUNT_PRICE AS BIGINT)) AS SELLER_DISCOUNT_PRICE, SUM(CAST(T.SPOT_DISCOUNT_PRICE AS BIGINT)) AS SPOT_DISCOUNT_PRICE, SUM(CAST(T.LEVEL_DISCOUNT_PRICE AS BIGINT)) AS LEVEL_DISCOUNT_PRICE, SUM(CAST(T.SET_DISCOUNT_PRICE AS BIGINT)) AS SET_DISCOUNT_PRICE, SUM(CAST(T.CANCEL_COUPON_DISCOUNT_PRICE AS BIGINT)) AS CANCEL_COUPON_DISCOUNT_PRICE, SUM(CAST(T.CANCEL_SELLER_DISCOUNT_PRICE AS BIGINT)) AS CANCEL_SELLER_DISCOUNT_PRICE, SUM(CAST(T.CANCEL_SPOT_DISCOUNT_PRICE AS BIGINT)) AS CANCEL_SPOT_DISCOUNT_PRICE, SUM(CAST(T.CANCEL_LEVEL_DISCOUNT_PRICE AS BIGINT)) AS CANCEL_LEVEL_DISCOUNT_PRICE, SUM(CAST(T.CANCEL_SET_DISCOUNT_PRICE AS BIGINT)) AS CANCEL_SET_DISCOUNT_PRICE, SUM(CAST(T.SHIPPING AS BIGINT)) AS SHIPPING, SUM(CAST(-T.CANCEL_SHIPPING AS BIGINT)) AS CANCEL_SHIPPING FROM (
) T
ORDER BY T.SEARCH_DATE DESC

