/* saleson.shop.statistics.ShopStatisticsMapper.getCategoriesStatsListCount */ SELECT COUNT(*) FROM ( SELECT COUNT(*) FROM ( SELECT GL.UPPER_LOCGOV_NM , GL.LOCGOV_NM , CAT , SCNT , SAMT FROM ( SELECT OI.LOCGOV_CODE , OCG.NAME AS CAT , SUM(OI.ORDER_QUANTITY) AS SCNT , SUM(OI.SALE_PRICE) AS SAMT FROM OP_ORDER_ITEM AS OI LEFT OUTER JOIN OP_USER_BIRTHDAY OUB ON OI.USER_ID = OUB.USER_ID JOIN OP_ITEM_CATEGORY OIC ON OI.ITEM_ID = OIC.ITEM_ID JOIN OP_CATEGORY OC ON OIC.CATEGORY_ID = OC.CATEGORY_ID JOIN OP_CATEGORY_GROUP OCG ON OC.CATEGORY_GROUP_ID = OCG.CATEGORY_GROUP_ID WHERE 1 = 1 AND OI.ORDER_STATUS = '40' AND SUBSTR(OI.SALES_DATE, 1, 8) BETWEEN #{startDate} AND #{endDate}
AND OI.LOCGOV_CODE = #{locgovCode}
GROUP BY OI.LOCGOV_CODE, OCG.NAME ) AS T JOIN G_LOCGOV GL ON GL.LOCGOV_CODE = T.LOCGOV_CODE ORDER BY LOCGOV_NM ) AS RS GROUP BY RS.UPPER_LOCGOV_NM, RS.LOCGOV_NM ) T

/* saleson.shop.statistics.ShopStatisticsMapper.getCategoriesStatsList */ SELECT RS.UPPER_LOCGOV_NM AS UPPER_LOCGOV_NM , RS.LOCGOV_NM AS LOCGOV_NM , SUM(CASE WHEN RS.CAT = '수산물' THEN RS.SCNT ELSE 0 END) AS MP_CNT , SUM(CASE WHEN RS.CAT = '수산물' THEN RS.SAMT ELSE 0 END) AS MP_AMT , SUM(CASE WHEN RS.CAT = '농축산물' THEN RS.SCNT ELSE 0 END) AS ALP_CNT , SUM(CASE WHEN RS.CAT = '농축산물' THEN RS.SAMT ELSE 0 END) AS ALP_AMT , SUM(CASE WHEN RS.CAT = '지역상품권' THEN RS.SCNT ELSE 0 END) AS LV_CNT , SUM(CASE WHEN RS.CAT = '지역상품권' THEN RS.SAMT ELSE 0 END) AS LV_AMT , SUM(CASE WHEN RS.CAT = '생활용품' THEN RS.SCNT ELSE 0 END) AS HG_CNT , SUM(CASE WHEN RS.CAT = '생활용품' THEN RS.SAMT ELSE 0 END) AS HG_AMT , SUM(CASE WHEN RS.CAT = '가공식품' THEN RS.SCNT ELSE 0 END) AS PF_CNT , SUM(CASE WHEN RS.CAT = '가공식품' THEN RS.SAMT ELSE 0 END) AS PF_AMT , SUM(CASE WHEN RS.CAT = '관광서비스' THEN RS.SCNT ELSE 0 END) AS TS_CNT , SUM(CASE WHEN RS.CAT = '관광서비스' THEN RS.SAMT ELSE 0 END) AS TS_AMT , SUM(RS.SCNT) AS TOTAL_CNT , SUM(RS.SAMT) AS TOTAL_AMT FROM ( SELECT GL.UPPER_LOCGOV_NM , GL.LOCGOV_NM , CAT , SCNT , SAMT FROM ( SELECT OI.LOCGOV_CODE , OCG.NAME AS CAT , SUM(OI.ORDER_QUANTITY) AS SCNT , SUM(OI.SALE_PRICE) AS SAMT FROM OP_ORDER_ITEM AS OI LEFT OUTER JOIN OP_USER_BIRTHDAY OUB ON OI.USER_ID = OUB.USER_ID JOIN OP_ITEM_CATEGORY OIC ON OI.ITEM_ID = OIC.ITEM_ID JOIN OP_CATEGORY OC ON OIC.CATEGORY_ID = OC.CATEGORY_ID JOIN OP_CATEGORY_GROUP OCG ON OC.CATEGORY_GROUP_ID = OCG.CATEGORY_GROUP_ID WHERE 1 = 1 AND OI.ORDER_STATUS = '40' AND SUBSTR(OI.SALES_DATE, 1, 8) BETWEEN #{startDate} AND #{endDate}
AND OI.LOCGOV_CODE = #{locgovCode}
GROUP BY OI.LOCGOV_CODE, OCG.NAME ) AS T JOIN G_LOCGOV GL ON GL.LOCGOV_CODE = T.LOCGOV_CODE ORDER BY LOCGOV_NM ) AS RS GROUP BY RS.UPPER_LOCGOV_NM, RS.LOCGOV_NM

