GROUP BY W.ITEM_ID ORDER BY REGISTRATION_NUMBER DESC

/* saleson.shop.statistics.ShopStatisticsMapper.getMonthLocgovItemStat */ SELECT INFO.LOCGOV_CODE , LOC.UPPER_LOCGOV_NM , LOC.LOCGOV_NM , MAX(INFO.ITEM_TOTAL_CNT) AS ITEM_TOTAL_CNT , MAX(INFO.TOUR_CNT) AS TOUR_CNT , MAX(INFO.PROCESS_CNT) AS PROCESS_CNT , MAX(INFO.DAILY_CNT) AS DAILY_CNT , MAX(INFO.TICKET_CNT) AS TICKET_CNT , MAX(INFO.FARM_CNT) AS FARM_CNT , MAX(INFO.AQUATIC_CNT) AS AQUATIC_CNT , MAX(INFO.ORDER_TOTAL_CNT) AS ORDER_TOTAL_CNT , MAX(INFO.SALE_PRICE) AS SALE_PRICE , MAX(INFO.TOP1) AS TOP1 , MAX(INFO.TOP2) AS TOP2 , MAX(INFO.TOP3) AS TOP3 , SUM(MAX(INFO.ITEM_TOTAL_CNT)) OVER() AS ITEM_TOTAL_ALL , SUM(MAX(INFO.TOUR_CNT)) OVER() AS TOUR_TOTAL_ALL , SUM(MAX(INFO.PROCESS_CNT)) OVER() AS PROCESS_TOTAL_ALL , SUM(MAX(INFO.DAILY_CNT)) OVER() AS DAILY_TOTAL_ALL , SUM(MAX(INFO.TICKET_CNT)) OVER() AS TICKET_TOTAL_ALL , SUM(MAX(INFO.FARM_CNT)) OVER() AS FARM_TOTAL_ALL , SUM(MAX(INFO.AQUATIC_CNT)) OVER() AS AQUATIC_TOTAL_ALL , SUM(MAX(INFO.ORDER_TOTAL_CNT)) OVER() AS ORDER_TOTAL_ALL , SUM(MAX(INFO.SALE_PRICE)) OVER() AS SALE_PRICE_TOTAL_ALL , INFO.ALL_TOP1_2 AS ALL_TOP1, INFO.ALL_TOP2_2 AS ALL_TOP2, INFO.ALL_TOP3_2 AS ALL_TOP3 FROM ( SELECT * , (TOUR_CNT + PROCESS_CNT + DAILY_CNT + TICKET_CNT + FARM_CNT + AQUATIC_CNT) AS ITEM_TOTAL_CNT , MAX(ALL_TOP1) OVER(PARTITION BY LOCGOV_CODE) AS ALL_TOP1_2 , MAX(ALL_TOP2) OVER(PARTITION BY LOCGOV_CODE) AS ALL_TOP2_2 , MAX(ALL_TOP3) OVER(PARTITION BY LOCGOV_CODE) AS ALL_TOP3_2 FROM ( SELECT LOCGOV_CODE ,
CAST(COUNT(DISTINCT DECODE(CODE, 'tour', ITEM_ID, NULL)) AS BIGINT) AS TOUR_CNT , CAST(COUNT(DISTINCT DECODE(CODE, 'process', ITEM_ID, NULL)) AS BIGINT) AS PROCESS_CNT , CAST(COUNT(DISTINCT DECODE(CODE, 'daily', ITEM_ID, NULL)) AS BIGINT) AS DAILY_CNT , CAST(COUNT(DISTINCT DECODE(CODE, 'ticket', ITEM_ID, NULL)) AS BIGINT) AS TICKET_CNT , CAST(COUNT(DISTINCT DECODE(CODE, 'farm', ITEM_ID, NULL)) AS BIGINT) AS FARM_CNT , CAST(COUNT(DISTINCT DECODE(CODE, 'aquatic', ITEM_ID, NULL)) AS BIGINT) AS AQUATIC_CNT , CAST(COUNT(DISTINCT CONCAT(ORDER_CODE, '|', ORDER_SEQUENCE, '|', ITEM_SEQUENCE)) AS BIGINT) AS ORDER_TOTAL_CNT , CAST(SUM(CASE WHEN ORDER_CODE_CNT = 0 THEN 0 ELSE CAST(SALE_PRICE AS NUMERIC(38, 15)) / ORDER_CODE_CNT END ) AS BIGINT) AS SALE_PRICE , GROUP_CONCAT(DISTINCT TOP1 SEPARATOR '^') TOP1 , GROUP_CONCAT(DISTINCT TOP2 SEPARATOR '^') TOP2 , GROUP_CONCAT(DISTINCT TOP3 SEPARATOR '^') TOP3 , GROUP_CONCAT(DISTINCT ALL_TOP1 SEPARATOR '^') ALL_TOP1 , GROUP_CONCAT(DISTINCT ALL_TOP2 SEPARATOR '^') ALL_TOP2 , GROUP_CONCAT(DISTINCT ALL_TOP3 SEPARATOR '^') ALL_TOP3 FROM ( SELECT * , IFNULL(DECODE(ORDER_RANK, 1, CONCAT(ITEM_NAME, '|', ITEM_BUY_CNT)), '') AS TOP1 , IFNULL(DECODE(ORDER_RANK, 2, CONCAT(ITEM_NAME, '|', ITEM_BUY_CNT)), '') AS TOP2 , IFNULL(DECODE(ORDER_RANK, 3, CONCAT(ITEM_NAME, '|', ITEM_BUY_CNT)), '') AS TOP3 , IFNULL(DECODE(ALL_ORDER_RANK, 1, CONCAT(ITEM_NAME, '|', ITEM_BUY_CNT)), '') AS ALL_TOP1 , IFNULL(DECODE(ALL_ORDER_RANK, 2, CONCAT(ITEM_NAME, '|', ITEM_BUY_CNT)), '') AS ALL_TOP2 , IFNULL(DECODE(ALL_ORDER_RANK, 3, CONCAT(ITEM_NAME, '|', ITEM_BUY_CNT)), '') AS ALL_TOP3 , COUNT(ORDER_CODE) OVER(PARTITION BY ORDER_CODE, ORDER_SEQUENCE, ITEM_SEQUENCE) AS ORDER_CODE_CNT FROM ( SELECT /*+ USE_MERGE(OI) */ I.LOCGOV_CODE , I.CODE, I.ITEM_ID, OI.ORDER_CODE, OI.ORDER_SEQUENCE, OI.ITEM_SEQUENCE, I.ITEM_NAME, OI.ITEM_ID AS ORDER_ITEM_ID, IFNULL(OI.ITEM_BUY_CNT, 0) AS ITEM_BUY_CNT, IFNULL(OI.SALE_PRICE, 0) AS SALE_PRICE, IFNULL(OI.QUANTITY, 0) AS QUANTITY, IFNULL(OI.ETC_AMT, 0) AS ETC_AMT, DENSE_RANK() OVER(PARTITION BY I.LOCGOV_CODE ORDER BY OI.ITEM_BUY_CNT DESC) AS ORDER_RANK, DENSE_RANK() OVER(ORDER BY OI.ITEM_BUY_CNT DESC) AS ALL_ORDER_RANK FROM ( SELECT I.* , S.LOCGOV_CODE , G.CODE FROM ( SELECT I.ITEM_ID, IC.CATEGORY_ID, I.ITEM_NAME, I.SELLER_ID FROM OP_ITEM I , OP_ITEM_CATEGORY IC WHERE I.DATA_STATUS_CODE = '1' AND I.DISPLAY_FLAG = 'Y' AND I.ITEM_DATA_TYPE = '1' AND I.ITEM_TYPE IN ('1', '3') AND I.PRIVATE_TYPE IN ('000') AND I.ITEM_ID = IC.ITEM_ID ) I , OP_CATEGORY C , OP_CATEGORY_GROUP G , OP_SELLER S , G_LOCGOV L WHERE 1 = 1 AND I.CATEGORY_ID = C.CATEGORY_ID AND C.CATEGORY_GROUP_ID = G.CATEGORY_GROUP_ID AND C.CATEGORY_FLAG = 'Y' AND G.CATEGORY_GROUP_FLAG = 'Y' AND I.SELLER_ID = S.SELLER_ID AND S.LOCGOV_CODE = L.LOCGOV_CODE AND S.STATUS_CODE = '2'
AND S.LOCGOV_CODE = #{locgovCode}
AND S.LOCGOV_CODE IN (SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{upperLocgovCode})
ORDER BY I.ITEM_ID ) I , ( SELECT ITEM_ID , CAST(IFNULL(SALE_PRICE, 0) AS BIGINT) * CAST(IFNULL(QUANTITY, 0) AS BIGINT) + CAST(IFNULL(ETC_AMT, 0) AS BIGINT) AS SALE_PRICE , QUANTITY ,
ORDER_CODE, ORDER_SEQUENCE, ITEM_SEQUENCE, ETC_AMT , IFNULL(SUM(1) OVER(PARTITION BY ITEM_ID), 0) AS ITEM_BUY_CNT FROM OP_ORDER_ITEM WHERE 1 = 1 AND ORDER_STATUS IN ('10', '20', '30', '35', '40', '50', '55', '58', '59')
AND PAY_DATE BETWEEN CONCAT(#{searchYearMonth}, '00000000') AND CONCAT(#{searchYearMonth}, '99999999') ) OI WHERE 1 = 1 AND OI.ITEM_ID(+) = I.ITEM_ID ) ) GROUP BY LOCGOV_CODE UNION ALL SELECT LOCGOV_CODE ,
0 AS TOUR_CNT , 0 AS PROCESS_CNT , 0 AS DAILY_CNT , 0 AS TICKET_CNT , 0 AS FARM_CNT , 0 AS AQUATIC_CNT , 0 AS ITEM_ORDER_CNT , 0 AS SALE_PRICE , '' AS TOP1 , '' AS TOP2 , '' AS TOP3 , '' AS ALL_TOP1 , '' AS ALL_TOP2 , '' AS ALL_TOP3 FROM G_LOCGOV WHERE USE_AT = 'Y'
AND LOCGOV_CODE = #{locgovCode}
AND LOCGOV_CODE IN (SELECT LOCGOV_CODE FROM G_LOCGOV WHERE UPPER_LOCGOV_CODE = #{upperLocgovCode})
) ) INFO , G_LOCGOV LOC WHERE LOC.LOCGOV_CODE(+) = INFO.LOCGOV_CODE GROUP BY INFO.LOCGOV_CODE ORDER BY INFO.LOCGOV_CODE

/* saleson.shop.statistics.ShopStatisticsMapper.getOrderCountAmtRateForDay 전년대비 금일 누적 주문금액/주문건수 */ SELECT LOCGOV_CODE , NOW_DAY_SALE_AMT /* 금일 주문 금액 */ , YST_DAY_SALE_AMT /* 전일 주문 금액 */ , NOW_YEAR_ADD_TOTAL_SALE_AMT /* 금년 금일 누적 총 주문 금액 */ , BF_YEAR_ADD_TOTAL_SALE_AMT /* 전년 금일 누적 총 주문 금액 */ , CASE WHEN YST_DAY_SALE_AMT = 0 THEN 0 ELSE ROUND(NOW_DAY_SALE_AMT * 100.0 / YST_DAY_SALE_AMT, 2) END AS DIF_DAY_SALE_AMT /* 전일 대비 금일 주문 금액 증감률 */ , CASE WHEN BF_YEAR_ADD_TOTAL_SALE_AMT = 0 THEN 0 ELSE ROUND(NOW_YEAR_ADD_TOTAL_SALE_AMT * 100.0 / BF_YEAR_ADD_TOTAL_SALE_AMT, 2) END AS DIF_YEAR_SALE_AMT /* 전년 금일 대비 금년 금일 주문 금액 증감률 */ , NOW_DAY_CNT /* 금일 주문 건수 */ , YST_DAY_CNT /* 전일 주문 건수 */ , NOW_YEAR_ADD_TOTAL_CNT /* 금년 금일 총 누적 주문 건수 */ , BF_YEAR_ADD_TOTAL_CNT /* 전년 금일 총 누적 주문 건수 */ , CASE WHEN YST_DAY_CNT = 0 THEN 0 ELSE ROUND(NOW_DAY_CNT * 100.0 / YST_DAY_CNT, 2) END AS DIF_DAY_CNT /* 전일 대비 금일 주문 건수 증감률 */ , CASE WHEN BF_YEAR_ADD_TOTAL_CNT = 0 THEN 0 ELSE ROUND(NOW_YEAR_ADD_TOTAL_CNT * 100.0 / BF_YEAR_ADD_TOTAL_CNT, 2) END AS DIF_YEAR_CNT /* 전년 금일 대비 금년 금일 누적 총 주문 건수 증감률 */ FROM ( SELECT L.LOCGOV_CODE , IFNULL(NOW_YEAR_ADD_TOTAL_SALE_AMT, 0) AS NOW_YEAR_ADD_TOTAL_SALE_AMT , IFNULL(BF_YEAR_ADD_TOTAL_SALE_AMT, 0) AS BF_YEAR_ADD_TOTAL_SALE_AMT , IFNULL(NOW_DAY_SALE_AMT, 0) AS NOW_DAY_SALE_AMT , IFNULL(YST_DAY_SALE_AMT, 0) AS YST_DAY_SALE_AMT , IFNULL(NOW_YEAR_ADD_TOTAL_CNT, 0) AS NOW_YEAR_ADD_TOTAL_CNT , IFNULL(BF_YEAR_ADD_TOTAL_CNT, 0) AS BF_YEAR_ADD_TOTAL_CNT , IFNULL(NOW_DAY_CNT, 0) AS NOW_DAY_CNT , IFNULL(YST_DAY_CNT, 0) AS YST_DAY_CNT FROM G_LOCGOV L LEFT JOIN ( SELECT IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{searchDate}, 1, 4) THEN SALE_AMT ELSE 0 END ), 0) AS NOW_YEAR_ADD_TOTAL_SALE_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{searchDate}, 1, 4) THEN 0 ELSE SALE_AMT END ), 0) AS BF_YEAR_ADD_TOTAL_SALE_AMT , IFNULL(SUM(CASE WHEN PAY_DATE = #{searchDate} THEN SALE_AMT ELSE 0 END ), 0) AS NOW_DAY_SALE_AMT , IFNULL(SUM(CASE WHEN PAY_DATE = TO_CHAR(ADDDATE(TO_DATE(#{searchDate}, 'YYYYMMDD'), INTERVAL -1 DAY), 'YYYYMMDD') THEN SALE_AMT ELSE 0 END ), 0) AS YST_DAY_SALE_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{searchDate}, 1, 4) THEN 1 ELSE 0 END ), 0) AS NOW_YEAR_ADD_TOTAL_CNT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{searchDate}, 1, 4) THEN 0 ELSE 1 END ), 0) AS BF_YEAR_ADD_TOTAL_CNT , IFNULL(SUM(CASE WHEN PAY_DATE = #{searchDate} THEN 1 ELSE 0 END ), 0) AS NOW_DAY_CNT , IFNULL(SUM(CASE WHEN PAY_DATE = TO_CHAR(ADDDATE(TO_DATE(#{searchDate}, 'YYYYMMDD'), INTERVAL -1 DAY), 'YYYYMMDD') THEN 1 ELSE 0 END ), 0) AS YST_DAY_CNT FROM ( SELECT CAST(OI.SALE_PRICE * OI.QUANTITY + OI.ETC_AMT AS BIGINT) AS SALE_AMT , SUBSTRING(OI.PAY_DATE, 1, 8) AS PAY_DATE , SUBSTRING(OI.PAY_DATE, 1, 4) AS PAY_YEAR , OI.SELLER_ID , OI.ORDER_CODE , OI.ITEM_SEQUENCE , OS.LOCGOV_CODE FROM OP_ORDER_ITEM OI LEFT JOIN OP_SELLER OS ON OS.SELLER_ID = OI.SELLER_ID WHERE 1=1 AND OI.PAY_DATE BETWEEN CONCAT(SUBSTRING(#{searchDate}, 1, 4), '0101000000') AND CONCAT(#{searchDate}, '235959') AND OI.ORDER_STATUS NOT IN ('0', '65', '75')
AND L.LOCGOV_CODE = #{locgovCode}
UNION SELECT CAST(OI.SALE_PRICE * OI.QUANTITY + OI.ETC_AMT AS BIGINT) AS SALE_AMT , SUBSTRING(OI.PAY_DATE, 1, 8) AS PAY_DATE , SUBSTRING(OI.PAY_DATE, 1, 4) AS PAY_YEAR , OI.SELLER_ID , OI.ORDER_CODE , OI.ITEM_SEQUENCE , OS.LOCGOV_CODE FROM OP_ORDER_ITEM OI LEFT JOIN OP_SELLER OS ON OS.SELLER_ID = OI.SELLER_ID WHERE 1=1 AND OI.PAY_DATE BETWEEN CONCAT(TO_CHAR(ADDDATE(TO_DATE(#{searchDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY'), '0101000000') AND CONCAT(TO_CHAR(ADDDATE(TO_DATE(#{searchDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYYMMDD'), '235959') AND OI.ORDER_STATUS NOT IN ('0', '65', '75')
AND L.LOCGOV_CODE = #{locgovCode}
) T_A WHERE 1=1 GROUP BY LOCGOV_CODE ) T_B ON L.LOCGOV_CODE = T_B.LOCGOV_CODE WHERE 1=1
AND L.LOCGOV_CODE = #{locgovCode}
) T_C

/* saleson.shop.statistics.ShopStatisticsMapper.getOrderCountAmtRateForMonth 지자체별 월별 전년 대비 주문금액/주문건수/비율 */ SELECT UPPER_LOCGOV_CODE , LOCGOV_CODE , UPPER_LOCGOV_NM , LOCGOV_NM , NOW_YR_1MM_WHOL_NTSL_AMT , BFR_YR_1MM_WHOL_NTSL_AMT , CASE WHEN BFR_YR_1MM_WHOL_NTSL_AMT = 0 THEN -1 ELSE ROUND(NOW_YR_1MM_WHOL_NTSL_AMT * 100.0 / BFR_YR_1MM_WHOL_NTSL_AMT, 2) END AS WHOL_NTSL_AMT_1MM_RT , NOW_YR_2MM_WHOL_NTSL_AMT , BFR_YR_2MM_WHOL_NTSL_AMT , CASE WHEN BFR_YR_2MM_WHOL_NTSL_AMT = 0 THEN -1 ELSE ROUND(NOW_YR_2MM_WHOL_NTSL_AMT * 100.0 / BFR_YR_2MM_WHOL_NTSL_AMT, 2) END AS WHOL_NTSL_AMT_2MM_RT , NOW_YR_3MM_WHOL_NTSL_AMT , BFR_YR_3MM_WHOL_NTSL_AMT , CASE WHEN BFR_YR_3MM_WHOL_NTSL_AMT = 0 THEN -1 ELSE ROUND(NOW_YR_3MM_WHOL_NTSL_AMT * 100.0 / BFR_YR_3MM_WHOL_NTSL_AMT, 2) END AS WHOL_NTSL_AMT_3MM_RT , NOW_YR_4MM_WHOL_NTSL_AMT , BFR_YR_4MM_WHOL_NTSL_AMT , CASE WHEN BFR_YR_4MM_WHOL_NTSL_AMT = 0 THEN -1 ELSE ROUND(NOW_YR_4MM_WHOL_NTSL_AMT * 100.0 / BFR_YR_4MM_WHOL_NTSL_AMT, 2) END AS WHOL_NTSL_AMT_4MM_RT , NOW_YR_5MM_WHOL_NTSL_AMT , BFR_YR_5MM_WHOL_NTSL_AMT , CASE WHEN BFR_YR_5MM_WHOL_NTSL_AMT = 0 THEN -1 ELSE ROUND(NOW_YR_5MM_WHOL_NTSL_AMT * 100.0 / BFR_YR_5MM_WHOL_NTSL_AMT, 2) END AS WHOL_NTSL_AMT_5MM_RT , NOW_YR_6MM_WHOL_NTSL_AMT , BFR_YR_6MM_WHOL_NTSL_AMT , CASE WHEN BFR_YR_6MM_WHOL_NTSL_AMT = 0 THEN -1 ELSE ROUND(NOW_YR_6MM_WHOL_NTSL_AMT * 100.0 / BFR_YR_6MM_WHOL_NTSL_AMT, 2) END AS WHOL_NTSL_AMT_6MM_RT , NOW_YR_7MM_WHOL_NTSL_AMT , BFR_YR_7MM_WHOL_NTSL_AMT , CASE WHEN BFR_YR_7MM_WHOL_NTSL_AMT = 0 THEN -1 ELSE ROUND(NOW_YR_7MM_WHOL_NTSL_AMT * 100.0 / BFR_YR_7MM_WHOL_NTSL_AMT, 2) END AS WHOL_NTSL_AMT_7MM_RT , NOW_YR_8MM_WHOL_NTSL_AMT , BFR_YR_8MM_WHOL_NTSL_AMT , CASE WHEN BFR_YR_8MM_WHOL_NTSL_AMT = 0 THEN -1 ELSE ROUND(NOW_YR_8MM_WHOL_NTSL_AMT * 100.0 / BFR_YR_8MM_WHOL_NTSL_AMT, 2) END AS WHOL_NTSL_AMT_8MM_RT , NOW_YR_9MM_WHOL_NTSL_AMT , BFR_YR_9MM_WHOL_NTSL_AMT , CASE WHEN BFR_YR_9MM_WHOL_NTSL_AMT = 0 THEN -1 ELSE ROUND(NOW_YR_9MM_WHOL_NTSL_AMT * 100.0 / BFR_YR_9MM_WHOL_NTSL_AMT, 2) END AS WHOL_NTSL_AMT_9MM_RT , NOW_YR_10MM_WHOL_NTSL_AMT , BFR_YR_10MM_WHOL_NTSL_AMT , CASE WHEN BFR_YR_10MM_WHOL_NTSL_AMT = 0 THEN -1 ELSE ROUND(NOW_YR_10MM_WHOL_NTSL_AMT * 100.0 / BFR_YR_10MM_WHOL_NTSL_AMT, 2) END AS WHOL_NTSL_AMT_10MM_RT , NOW_YR_11MM_WHOL_NTSL_AMT , BFR_YR_11MM_WHOL_NTSL_AMT , CASE WHEN BFR_YR_11MM_WHOL_NTSL_AMT = 0 THEN -1 ELSE ROUND(NOW_YR_11MM_WHOL_NTSL_AMT * 100.0 / BFR_YR_11MM_WHOL_NTSL_AMT, 2) END AS WHOL_NTSL_AMT_11MM_RT , NOW_YR_12MM_WHOL_NTSL_AMT , BFR_YR_12MM_WHOL_NTSL_AMT , CASE WHEN BFR_YR_12MM_WHOL_NTSL_AMT = 0 THEN -1 ELSE ROUND(NOW_YR_12MM_WHOL_NTSL_AMT * 100.0 / BFR_YR_12MM_WHOL_NTSL_AMT, 2) END AS WHOL_NTSL_AMT_12MM_RT , NOW_YR_1MM_WHOL_NTSL_NOCS , BFR_YR_1MM_WHOL_NTSL_NOCS , CASE WHEN BFR_YR_1MM_WHOL_NTSL_NOCS = 0 THEN -1 ELSE ROUND(NOW_YR_1MM_WHOL_NTSL_NOCS * 100.0 / BFR_YR_1MM_WHOL_NTSL_NOCS, 2) END AS WHOL_NTSL_NOCS_1MM_RT , NOW_YR_2MM_WHOL_NTSL_NOCS , BFR_YR_2MM_WHOL_NTSL_NOCS , CASE WHEN BFR_YR_2MM_WHOL_NTSL_NOCS = 0 THEN -1 ELSE ROUND(NOW_YR_2MM_WHOL_NTSL_NOCS * 100.0 / BFR_YR_2MM_WHOL_NTSL_NOCS, 2) END AS WHOL_NTSL_NOCS_2MM_RT , NOW_YR_3MM_WHOL_NTSL_NOCS , BFR_YR_3MM_WHOL_NTSL_NOCS , CASE WHEN BFR_YR_3MM_WHOL_NTSL_NOCS = 0 THEN -1 ELSE ROUND(NOW_YR_3MM_WHOL_NTSL_NOCS * 100.0 / BFR_YR_3MM_WHOL_NTSL_NOCS, 2) END AS WHOL_NTSL_NOCS_3MM_RT , NOW_YR_4MM_WHOL_NTSL_NOCS , BFR_YR_4MM_WHOL_NTSL_NOCS , CASE WHEN BFR_YR_4MM_WHOL_NTSL_NOCS = 0 THEN -1 ELSE ROUND(NOW_YR_4MM_WHOL_NTSL_NOCS * 100.0 / BFR_YR_4MM_WHOL_NTSL_NOCS, 2) END AS WHOL_NTSL_NOCS_4MM_RT , NOW_YR_5MM_WHOL_NTSL_NOCS , BFR_YR_5MM_WHOL_NTSL_NOCS , CASE WHEN BFR_YR_5MM_WHOL_NTSL_NOCS = 0 THEN -1 ELSE ROUND(NOW_YR_5MM_WHOL_NTSL_NOCS * 100.0 / BFR_YR_5MM_WHOL_NTSL_NOCS, 2) END AS WHOL_NTSL_NOCS_5MM_RT , NOW_YR_6MM_WHOL_NTSL_NOCS , BFR_YR_6MM_WHOL_NTSL_NOCS , CASE WHEN BFR_YR_6MM_WHOL_NTSL_NOCS = 0 THEN -1 ELSE ROUND(NOW_YR_6MM_WHOL_NTSL_NOCS * 100.0 / BFR_YR_6MM_WHOL_NTSL_NOCS, 2) END AS WHOL_NTSL_NOCS_6MM_RT , NOW_YR_7MM_WHOL_NTSL_NOCS , BFR_YR_7MM_WHOL_NTSL_NOCS , CASE WHEN BFR_YR_7MM_WHOL_NTSL_NOCS = 0 THEN -1 ELSE ROUND(NOW_YR_7MM_WHOL_NTSL_NOCS * 100.0 / BFR_YR_7MM_WHOL_NTSL_NOCS, 2) END AS WHOL_NTSL_NOCS_7MM_RT , NOW_YR_8MM_WHOL_NTSL_NOCS , BFR_YR_8MM_WHOL_NTSL_NOCS , CASE WHEN BFR_YR_8MM_WHOL_NTSL_NOCS = 0 THEN -1 ELSE ROUND(NOW_YR_8MM_WHOL_NTSL_NOCS * 100.0 / BFR_YR_8MM_WHOL_NTSL_NOCS, 2) END AS WHOL_NTSL_NOCS_8MM_RT , NOW_YR_9MM_WHOL_NTSL_NOCS , BFR_YR_9MM_WHOL_NTSL_NOCS , CASE WHEN BFR_YR_9MM_WHOL_NTSL_NOCS = 0 THEN -1 ELSE ROUND(NOW_YR_9MM_WHOL_NTSL_NOCS * 100.0 / BFR_YR_9MM_WHOL_NTSL_NOCS, 2) END AS WHOL_NTSL_NOCS_9MM_RT , NOW_YR_10MM_WHOL_NTSL_NOCS , BFR_YR_10MM_WHOL_NTSL_NOCS , CASE WHEN BFR_YR_10MM_WHOL_NTSL_NOCS = 0 THEN -1 ELSE ROUND(NOW_YR_10MM_WHOL_NTSL_NOCS * 100.0 / BFR_YR_10MM_WHOL_NTSL_NOCS, 2) END AS WHOL_NTSL_NOCS_10MM_RT , NOW_YR_11MM_WHOL_NTSL_NOCS , BFR_YR_11MM_WHOL_NTSL_NOCS , CASE WHEN BFR_YR_11MM_WHOL_NTSL_NOCS = 0 THEN -1 ELSE ROUND(NOW_YR_11MM_WHOL_NTSL_NOCS * 100.0 / BFR_YR_11MM_WHOL_NTSL_NOCS, 2) END AS WHOL_NTSL_NOCS_11MM_RT , NOW_YR_12MM_WHOL_NTSL_NOCS , BFR_YR_12MM_WHOL_NTSL_NOCS , CASE WHEN BFR_YR_12MM_WHOL_NTSL_NOCS = 0 THEN -1 ELSE ROUND(NOW_YR_12MM_WHOL_NTSL_NOCS * 100.0 / BFR_YR_12MM_WHOL_NTSL_NOCS, 2) END AS WHOL_NTSL_NOCS_12MM_RT FROM ( SELECT UPPER_LOCGOV_CODE , LOCGOV_CODE , UPPER_LOCGOV_NM , LOCGOV_NM , SUM(NOW_YR_1MM_WHOL_NTSL_AMT) AS NOW_YR_1MM_WHOL_NTSL_AMT , SUM(BFR_YR_1MM_WHOL_NTSL_AMT) AS BFR_YR_1MM_WHOL_NTSL_AMT , SUM(NOW_YR_2MM_WHOL_NTSL_AMT) AS NOW_YR_2MM_WHOL_NTSL_AMT , SUM(BFR_YR_2MM_WHOL_NTSL_AMT) AS BFR_YR_2MM_WHOL_NTSL_AMT , SUM(NOW_YR_3MM_WHOL_NTSL_AMT) AS NOW_YR_3MM_WHOL_NTSL_AMT , SUM(BFR_YR_3MM_WHOL_NTSL_AMT) AS BFR_YR_3MM_WHOL_NTSL_AMT , SUM(NOW_YR_4MM_WHOL_NTSL_AMT) AS NOW_YR_4MM_WHOL_NTSL_AMT , SUM(BFR_YR_4MM_WHOL_NTSL_AMT) AS BFR_YR_4MM_WHOL_NTSL_AMT , SUM(NOW_YR_5MM_WHOL_NTSL_AMT) AS NOW_YR_5MM_WHOL_NTSL_AMT , SUM(BFR_YR_5MM_WHOL_NTSL_AMT) AS BFR_YR_5MM_WHOL_NTSL_AMT , SUM(NOW_YR_6MM_WHOL_NTSL_AMT) AS NOW_YR_6MM_WHOL_NTSL_AMT , SUM(BFR_YR_6MM_WHOL_NTSL_AMT) AS B