 IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 3 THEN SALE_AMT ELSE 0 END), 0) AS NOW_YR_3MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 4 THEN SALE_AMT ELSE 0 END), 0) AS NOW_YR_4MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 5 THEN SALE_AMT ELSE 0 END), 0) AS NOW_YR_5MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 6 THEN SALE_AMT ELSE 0 END), 0) AS NOW_YR_6MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 7 THEN SALE_AMT ELSE 0 END), 0) AS NOW_YR_7MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 8 THEN SALE_AMT ELSE 0 END), 0) AS NOW_YR_8MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 9 THEN SALE_AMT ELSE 0 END), 0) AS NOW_YR_9MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 10 THEN SALE_AMT ELSE 0 END), 0) AS NOW_YR_10MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 11 THEN SALE_AMT ELSE 0 END), 0) AS NOW_YR_11MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 12 THEN SALE_AMT ELSE 0 END), 0) AS NOW_YR_12MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 1 THEN SALE_AMT ELSE 0 END), 0) AS BFR_YR_1MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 2 THEN SALE_AMT ELSE 0 END), 0) AS BFR_YR_2MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 3 THEN SALE_AMT ELSE 0 END), 0) AS BFR_YR_3MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 4 THEN SALE_AMT ELSE 0 END), 0) AS BFR_YR_4MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 5 THEN SALE_AMT ELSE 0 END), 0) AS BFR_YR_5MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 6 THEN SALE_AMT ELSE 0 END), 0) AS BFR_YR_6MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 7 THEN SALE_AMT ELSE 0 END), 0) AS BFR_YR_7MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 8 THEN SALE_AMT ELSE 0 END), 0) AS BFR_YR_8MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 9 THEN SALE_AMT ELSE 0 END), 0) AS BFR_YR_9MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 10 THEN SALE_AMT ELSE 0 END), 0) AS BFR_YR_10MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 11 THEN SALE_AMT ELSE 0 END), 0) AS BFR_YR_11MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 12 THEN 1 ELSE 0 END), 0) AS BFR_YR_12MM_WHOL_NTSL_AMT , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 1 THEN 1 ELSE 0 END), 0) AS NOW_YR_1MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 2 THEN 1 ELSE 0 END), 0) AS NOW_YR_2MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 3 THEN 1 ELSE 0 END), 0) AS NOW_YR_3MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 4 THEN 1 ELSE 0 END), 0) AS NOW_YR_4MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 5 THEN 1 ELSE 0 END), 0) AS NOW_YR_5MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 6 THEN 1 ELSE 0 END), 0) AS NOW_YR_6MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 7 THEN 1 ELSE 0 END), 0) AS NOW_YR_7MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 8 THEN 1 ELSE 0 END), 0) AS NOW_YR_8MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 9 THEN 1 ELSE 0 END), 0) AS NOW_YR_9MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 10 THEN 1 ELSE 0 END), 0) AS NOW_YR_10MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 11 THEN 1 ELSE 0 END), 0) AS NOW_YR_11MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = SUBSTRING(#{startDate}, 1, 4) AND PAY_MONTH = 12 THEN 1 ELSE 0 END), 0) AS NOW_YR_12MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 1 THEN 1 ELSE 0 END), 0) AS BFR_YR_1MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 2 THEN 1 ELSE 0 END), 0) AS BFR_YR_2MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 3 THEN 1 ELSE 0 END), 0) AS BFR_YR_3MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 4 THEN 1 ELSE 0 END), 0) AS BFR_YR_4MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 5 THEN 1 ELSE 0 END), 0) AS BFR_YR_5MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 6 THEN 1 ELSE 0 END), 0) AS BFR_YR_6MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 7 THEN 1 ELSE 0 END), 0) AS BFR_YR_7MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 8 THEN 1 ELSE 0 END), 0) AS BFR_YR_8MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 9 THEN 1 ELSE 0 END), 0) AS BFR_YR_9MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 10 THEN 1 ELSE 0 END), 0) AS BFR_YR_10MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 11 THEN 1 ELSE 0 END), 0) AS BFR_YR_11MM_WHOL_NTSL_NOCS , IFNULL(SUM(CASE WHEN PAY_YEAR = TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYY') AND PAY_MONTH = 12 THEN 1 ELSE 0 END), 0) AS BFR_YR_12MM_WHOL_NTSL_NOCS FROM ( SELECT CAST(OI.SALE_PRICE * OI.QUANTITY + OI.ETC_AMT AS BIGINT) AS SALE_AMT , SUBSTRING(OI.PAY_DATE, 1, 8) AS PAY_DATE , CAST(SUBSTRING(OI.PAY_DATE, 5, 2) AS INT) AS PAY_MONTH , SUBSTRING(OI.PAY_DATE, 1, 4) AS PAY_YEAR , OI.SELLER_ID , OI.ORDER_CODE , OI.ITEM_SEQUENCE , OS.LOCGOV_CODE FROM OP_ORDER_ITEM OI LEFT JOIN OP_SELLER OS ON OS.SELLER_ID = OI.SELLER_ID WHERE 1=1 AND OI.PAY_DATE BETWEEN CONCAT(#{startDate}, '000000') AND CONCAT(#{endDate}, '235959') AND OI.ORDER_STATUS NOT IN ('0', '65', '75') UNION SELECT CAST(OI.SALE_PRICE * OI.QUANTITY + OI.ETC_AMT AS BIGINT) AS SALE_AMT , SUBSTRING(OI.PAY_DATE, 1, 8) AS PAY_DATE , CAST(SUBSTRING(OI.PAY_DATE, 5, 2) AS INT) AS PAY_MONTH , SUBSTRING(OI.PAY_DATE, 1, 4) AS PAY_YEAR , OI.SELLER_ID , OI.ORDER_CODE , OI.ITEM_SEQUENCE , OS.LOCGOV_CODE FROM OP_ORDER_ITEM OI LEFT JOIN OP_SELLER OS ON OS.SELLER_ID = OI.SELLER_ID WHERE 1=1 AND OI.PAY_DATE BETWEEN CONCAT(TO_CHAR(ADDDATE(TO_DATE(#{startDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYYMMDD'), '000000') AND CONCAT(TO_CHAR(ADDDATE(TO_DATE(#{endDate}, 'YYYYMMDD'), INTERVAL -1 YEAR), 'YYYYMMDD'), '235959') AND OI.ORDER_STATUS NOT IN ('0', '65', '75') ) T_A WHERE 1=1
AND LOCGOV_CODE = #{locgovCode}
GROUP BY LOCGOV_CODE ) T_B ON L.LOCGOV_CODE = T_B.LOCGOV_CODE WHERE 1=1
AND L.UPPER_LOCGOV_CODE = #{upperLocgovCode}
AND LOCGOV_CODE = #{locgovCode}
ORDER BY L.LOCGOV_CODE ) T_C GROUP BY LOCGOV_CODE ) T_D

WITH CURRENT_CNT AS ( SELECT /*+ USE_MERGE(B) */ A.UPPER_LOCGOV_NM , A.UPPER_LOCGOV_CODE , COUNT(B.ORDER_CODE) AS TOTAL , COUNT(DECODE(MONTH(B.POINT_USE_DE),1,B.ORDER_CODE)) AS MON_1 , COUNT(DECODE(MONTH(B.POINT_USE_DE),2,B.ORDER_CODE)) AS MON_2 , COUNT(DECODE(MONTH(B.POINT_USE_DE),3,B.ORDER_CODE)) AS MON_3 , COUNT(DECODE(MONTH(B.POINT_USE_DE),4,B.ORDER_CODE)) AS MON_4 , COUNT(DECODE(MONTH(B.POINT_USE_DE),5,B.ORDER_CODE)) AS MON_5 , COUNT(DECODE(MONTH(B.POINT_USE_DE),6,B.ORDER_CODE)) AS MON_6 , COUNT(DECODE(MONTH(B.POINT_USE_DE),7,B.ORDER_CODE)) AS MON_7 , COUNT(DECODE(MONTH(B.POINT_USE_DE),8,B.ORDER_CODE)) AS MON_8 , COUNT(DECODE(MONTH(B.POINT_USE_DE),9,B.ORDER_CODE)) AS MON_9 , COUNT(DECODE(MONTH(B.POINT_USE_DE),10,B.ORDER_CODE)) AS MON_10 , COUNT(DECODE(MONTH(B.POINT_USE_DE),11,B.ORDER_CODE)) AS MON_11 , COUNT(DECODE(MONTH(B.POINT_USE_DE),12,B.ORDER_CODE)) AS MON_12 FROM G_LOCGOV A LEFT JOIN ( SELECT B.CNTR_SN ,B.CNTR_LOCGOV_CODE ,A.POINT_USE_DE ,A.CNTR_USE_POINT ,A.ORDER_CODE FROM G_CNTR_USE_POINT A LEFT JOIN G_CNTR B ON A.CNTR_SN = B.CNTR_SN WHERE 1=1 AND A.USE_SE_CODE = '1' AND YEAR(A.POINT_USE_DE) = #{crtrYr}
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND '12'
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND MONTH(ADD_MONTHS(SYSDATE,-1))
) B ON A.LOCGOV_CODE = B.CNTR_LOCGOV_CODE GROUP BY A.UPPER_LOCGOV_CODE,A.UPPER_LOCGOV_NM ) , PREVIOUS_CNT AS ( SELECT /*+ USE_MERGE(B) */ A.UPPER_LOCGOV_NM , A.UPPER_LOCGOV_CODE , COUNT(B.ORDER_CODE) AS TOTAL , COUNT(DECODE(MONTH(B.POINT_USE_DE),1,B.ORDER_CODE)) AS MON_1 , COUNT(DECODE(MONTH(B.POINT_USE_DE),2,B.ORDER_CODE)) AS MON_2 , COUNT(DECODE(MONTH(B.POINT_USE_DE),3,B.ORDER_CODE)) AS MON_3 , COUNT(DECODE(MONTH(B.POINT_USE_DE),4,B.ORDER_CODE)) AS MON_4 , COUNT(DECODE(MONTH(B.POINT_USE_DE),5,B.ORDER_CODE)) AS MON_5 , COUNT(DECODE(MONTH(B.POINT_USE_DE),6,B.ORDER_CODE)) AS MON_6 , COUNT(DECODE(MONTH(B.POINT_USE_DE),7,B.ORDER_CODE)) AS MON_7 , COUNT(DECODE(MONTH(B.POINT_USE_DE),8,B.ORDER_CODE)) AS MON_8 , COUNT(DECODE(MONTH(B.POINT_USE_DE),9,B.ORDER_CODE)) AS MON_9 , COUNT(DECODE(MONTH(B.POINT_USE_DE),10,B.ORDER_CODE)) AS MON_10 , COUNT(DECODE(MONTH(B.POINT_USE_DE),11,B.ORDER_CODE)) AS MON_11 , COUNT(DECODE(MONTH(B.POINT_USE_DE),12,B.ORDER_CODE)) AS MON_12 FROM G_LOCGOV A LEFT JOIN ( SELECT B.CNTR_SN ,B.CNTR_LOCGOV_CODE ,A.POINT_USE_DE ,A.CNTR_USE_POINT ,A.ORDER_CODE FROM G_CNTR_USE_POINT A LEFT JOIN G_CNTR B ON A.CNTR_SN = B.CNTR_SN WHERE 1=1 AND A.USE_SE_CODE = '1' AND YEAR(A.POINT_USE_DE) = #{paramPrvYr}
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND '12'
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND MONTH(ADD_MONTHS(SYSDATE,-1))
) B ON A.LOCGOV_CODE = B.CNTR_LOCGOV_CODE GROUP BY A.UPPER_LOCGOV_CODE,A.UPPER_LOCGOV_NM ) SELECT /*+ USE_MERGE(B) */ NVL(A.UPPER_LOCGOV_NM,'총계') as UPPER_LOCGOV_NM ,NVL(A.UPPER_LOCGOV_CODE, '00000') AS UPPER_LOCGOV_CODE ,SUM(NVL(A.TOTAL,0)) AS NOW_YR ,SUM(NVL(B.TOTAL,0)) AS PRVYR ,SUM(NVL(A.MON_1,0)) AS NOW_YR_JAN ,SUM(NVL(B.MON_1,0)) AS PRVYR_JAN ,DECODE(B.MON_1,0,0,FORMAT((A.MON_1*1.0)/(B.MON_1*1.0),4)) AS PRVYR_NOW_YR_RT_JAN ,SUM(NVL(A.MON_2,0)) AS NOW_YR_FEB ,SUM(NVL(B.MON_2,0)) AS PRVYR_FEB ,DECODE(B.MON_2,0,0,FORMAT((A.MON_2*1.0)/(B.MON_2*1.0),4)) AS PRVYR_NOW_YR_RT_FEB ,SUM(NVL(A.MON_3,0)) AS NOW_YR_MAR ,SUM(NVL(B.MON_3,0)) AS PRVYR_MAR ,DECODE(B.MON_3,0,0,FORMAT((A.MON_3*1.0)/(B.MON_3*1.0),4)) AS PRVYR_NOW_YR_RT_MAR ,SUM(NVL(A.MON_4,0)) AS NOW_YR_APR ,SUM(NVL(B.MON_4,0)) AS PRVYR_APR ,DECODE(B.MON_4,0,0,FORMAT((A.MON_4*1.0)/(B.MON_4*1.0),4)) AS PRVYR_NOW_YR_RT_APR ,SUM(NVL(A.MON_5,0)) AS NOW_YR_MAY ,SUM(NVL(B.MON_5,0)) AS PRVYR_MAY ,DECODE(B.MON_5,0,0,FORMAT((A.MON_5*1.0)/(B.MON_5*1.0),4)) AS PRVYR_NOW_YR_RT_MAY ,SUM(NVL(A.MON_6,0)) AS NOW_YR_JUN ,SUM(NVL(B.MON_6,0)) AS PRVYR_JUN ,DECODE(B.MON_6,0,0,FORMAT((A.MON_6*1.0)/(B.MON_6*1.0),4)) AS PRVYR_NOW_YR_RT_JUN ,SUM(NVL(A.MON_7,0)) AS NOW_YR_JUL ,SUM(NVL(B.MON_7,0)) AS PRVYR_JUL ,DECODE(B.MON_7,0,0,FORMAT((A.MON_7*1.0)/(B.MON_7*1.0),4)) AS PRVYR_NOW_YR_RT_JUL ,SUM(NVL(A.MON_8,0)) AS NOW_YR_AUG ,SUM(NVL(B.MON_8,0)) AS PRVYR_AUG ,DECODE(B.MON_8,0,0,FORMAT((A.MON_8*1.0)/(B.MON_8*1.0),4)) AS PRVYR_NOW_YR_RT_AUG ,SUM(NVL(A.MON_9,0)) AS NOW_YR_SEP ,SUM(NVL(B.MON_9,0)) AS PRVYR_SEP ,DECODE(B.MON_9,0,0,FORMAT((A.MON_9*1.0)/(B.MON_9*1.0),4)) AS PRVYR_NOW_YR_RT_SEP ,SUM(NVL(A.MON_10,0)) AS NOW_YR_OCT ,SUM(NVL(B.MON_10,0)) AS PRVYR_OCT ,DECODE(B.MON_10,0,0,FORMAT((A.MON_10*1.0)/(B.MON_10*1.0),4)) AS PRVYR_NOW_YR_RT_OCT ,SUM(NVL(A.MON_11,0)) AS NOW_YR_NOV ,SUM(NVL(B.MON_11,0)) AS PRVYR_NOV ,DECODE(B.MON_11,0,0,FORMAT((A.MON_11*1.0)/(B.MON_11*1.0),4)) AS PRVYR_NOW_YR_RT_NOV ,SUM(NVL(A.MON_12,0)) AS NOW_YR_DEC ,SUM(NVL(B.MON_12,0)) AS PRVYR_DEC ,DECODE(B.MON_12,0,0,FORMAT((A.MON_12*1.0)/(B.MON_12*1.0),4)) AS PRVYR_NOW_YR_RT_DEC FROM CURRENT_CNT A LEFT JOIN PREVIOUS_CNT B ON A.UPPER_LOCGOV_CODE = B.UPPER_LOCGOV_CODE GROUP BY A.UPPER_LOCGOV_CODE WITH ROLLUP ORDER BY A.UPPER_LOCGOV_CODE

WITH CURRENT_AMT AS ( SELECT /*+ USE_MERGE(B) */ A.UPPER_LOCGOV_NM , A.UPPER_LOCGOV_CODE , A.LOCGOV_CODE , A.LOCGOV_NM , NVL(SUM(DECODE(MONTH(B.CNTR_DE),1,B.CNTR_AMT)),0) AS MON_1 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),2,B.CNTR_AMT)),0) AS MON_2 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),3,B.CNTR_AMT)),0) AS MON_3 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),4,B.CNTR_AMT)),0) AS MON_4 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),5,B.CNTR_AMT)),0) AS MON_5 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),6,B.CNTR_AMT)),0) AS MON_6 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),7,B.CNTR_AMT)),0) AS MON_7 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),8,B.CNTR_AMT)),0) AS MON_8 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),9,B.CNTR_AMT)),0) AS MON_9 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),10,B.CNTR_AMT)),0) AS MON_10 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),11,B.CNTR_AMT)),0) AS MON_11 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),12,B.CNTR_AMT)),0) AS MON_12 FROM G_LOCGOV A LEFT OUTER JOIN G_CNTR B ON A.LOCGOV_CODE = B.CNTR_LOCGOV_CODE AND B.DELETE_AT ='N' AND B.STTEMNT_PAY_DE IS NOT NULL AND B.CNTR_STTUS_CODE = '200' AND YEAR(B.CNTR_DE) = #{crtrYr}
AND MONTH(B.CNTR_DE) BETWEEN '1' AND '12'
AND MONTH(B.CNTR_DE) BETWEEN '1' AND MONTH(ADD_MONTHS(SYSDATE,-1))
WHERE 1=1 GROUP BY A.LOCGOV_CODE , A.UPPER_LOCGOV_NM, A.LOCGOV_NM ) , CURRENT_TOTAL AS ( SELECT /*+ USE_MERGE(B) */ A.UPPER_LOCGOV_NM , A.UPPER_LOCGOV_CODE , A.LOCGOV_CODE , A.LOCGOV_NM , SUM(B.CNTR_AMT) AS TOT_POINT FROM G_LOCGOV A LEFT OUTER JOIN G_CNTR B ON A.LOCGOV_CODE = B.CNTR_LOCGOV_CODE AND B.DELETE_AT ='N' AND B.STTEMNT_PAY_DE IS NOT NULL AND B.CNTR_STTUS_CODE = '200' AND YEAR(B.CNTR_DE) = #{crtrYr}
AND MONTH(B.CNTR_DE) BETWEEN '1' AND '12'
AND MONTH(B.CNTR_DE) BETWEEN '1' AND MONTH(ADD_MONTHS(SYSDATE,-1))
WHERE 1=1 GROUP BY A.LOCGOV_CODE , A.UPPER_LOCGOV_NM, A.LOCGOV_NM ) , PREVIOUS_AMT AS ( SELECT /*+ USE_MERGE(B) */ A.UPPER_LOCGOV_NM , A.UPPER_LOCGOV_CODE , A.LOCGOV_CODE , A.LOCGOV_NM , NVL(SUM(DECODE(MONTH(B.CNTR_DE),1,B.CNTR_AMT)),0) AS MON_1 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),2,B.CNTR_AMT)),0) AS MON_2 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),3,B.CNTR_AMT)),0) AS MON_3 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),4,B.CNTR_AMT)),0) AS MON_4 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),5,B.CNTR_AMT)),0) AS MON_5 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),6,B.CNTR_AMT)),0) AS MON_6 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),7,B.CNTR_AMT)),0) AS MON_7 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),8,B.CNTR_AMT)),0) AS MON_8 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),9,B.CNTR_AMT)),0) AS MON_9 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),10,B.CNTR_AMT)),0) AS MON_10 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),11,B.CNTR_AMT)),0) AS MON_11 , NVL(SUM(DECODE(MONTH(B.CNTR_DE),12,B.CNTR_AMT)),0) AS MON_12 FROM G_LOCGOV A LEFT OUTER JOIN G_CNTR B ON A.LOCGOV_CODE = B.CNTR_LOCGOV_CODE AND B.DELETE_AT ='N' AND B.STTEMNT_PAY_DE IS NOT NULL AND B.CNTR_STTUS_CODE = '200' AND YEAR(B.CNTR_DE) = #{paramPrvYr}
AND MONTH(B.CNTR_DE) BETWEEN '1' AND '12'
AND MONTH(B.CNTR_DE) BETWEEN '1' AND MONTH(ADD_MONTHS(SYSDATE,-1))
WHERE 1=1 GROUP BY A.LOCGOV_CODE , A.UPPER_LOCGOV_NM, A.LOCGOV_NM ) , PREVIOUS_TOTAL AS ( SELECT /*+ USE_MERGE(B) */ A.UPPER_LOCGOV_NM , A.UPPER_LOCGOV_CODE , A.LOCGOV_CODE , A.LOCGOV_NM , SUM(B.CNTR_AMT) AS TOT_POINT FROM G_LOCGOV A LEFT OUTER JOIN G_CNTR B ON A.LOCGOV_CODE = B.CNTR_LOCGOV_CODE AND B.DELETE_AT ='N' AND B.STTEMNT_PAY_DE IS NOT NULL AND B.CNTR_STTUS_CODE = '200' AND YEAR(B.CNTR_DE) = #{paramPrvYr}
AND MONTH(B.CNTR_DE) BETWEEN '1' AND '12'
AND MONTH(B.CNTR_DE) BETWEEN '1' AND MONTH(ADD_MONTHS(SYSDATE,-1))
WHERE 1=1 GROUP BY A.LOCGOV_CODE , A.UPPER_LOCGOV_NM, A.LOCGOV_NM ) SELECT /*+ USE_IDX(UPPER_LOCGOV_CODE) USE_MERGE(B) USE_MERGE(C) */ DECODE(NVL(A.LOCGOV_CODE, '00000'),'00000' ,DECODE(NVL(A.UPPER_LOCGOV_CODE, '00000'),'00000','총계' ,(SELECT AA.UPPER_LOCGOV_NM FROM G_LOCGOV AA WHERE AA.UPPER_LOCGOV_CODE = A.UPPER_LOCGOV_CODE GROUP BY AA.UPPER_LOCGOV_NM)),A.UPPER_LOCGOV_NM) AS UPPER_LOCGOV_NM ,NVL(A.UPPER_LOCGOV_CODE, '00000') AS UPPER_LOCGOV_CODE ,DECODE(NVL(A.LOCGOV_CODE, '00000'),'00000',DECODE(NVL(A.UPPER_LOCGOV_CODE, '00000'),'00000','','소계'),A.LOCGOV_NM) AS LOCGOV_NM ,NVL(A.LOCGOV_CODE, '00000') AS LOCGOV_CODE ,SUM(NVL(C.TOT_POINT,0)) AS NOW_YR ,SUM(NVL(D.TOT_POINT,0)) AS PRVYR ,SUM(NVL(A.MON_1,0)) AS NOW_YR_JAN ,SUM(NVL(B.MON_1,0)) AS PRVYR_JAN ,DECODE(B.MON_1,0,'0',FORMAT((A.MON_1*1.0)/(B.MON_1*1.0),4)) AS PRVYR_NOW_YR_RT_JAN ,SUM(NVL(A.MON_2,0)) AS NOW_YR_FEB ,SUM(NVL(B.MON_2,0)) AS PRVYR_FEB ,DECODE(B.MON_2,0,'0',FORMAT((A.MON_2*1.0)/(B.MON_2*1.0),4)) AS PRVYR_NOW_YR_RT_FEB ,SUM(NVL(A.MON_3,0)) AS NOW_YR_MAR ,SUM(NVL(B.MON_3,0)) AS PRVYR_MAR ,DECODE(B.MON_3,0,'0',FORMAT((A.MON_3*1.0)/(B.MON_3*1.0),4)) AS PRVYR_NOW_YR_RT_MAR ,SUM(NVL(A.MON_4,0)) AS NOW_YR_APR ,SUM(NVL(B.MON_4,0)) AS PRVYR_APR ,DECODE(B.MON_4,0,'0',FORMAT((A.MON_4*1.0)/(B.MON_4*1.0),4)) AS PRVYR_NOW_YR_RT_APR ,SUM(NVL(A.MON_5,0)) AS NOW_YR_MAY ,SUM(NVL(B.MON_5,0)) AS PRVYR_MAY ,DECODE(B.MON_5,0,'0',FORMAT((A.MON_5*1.0)/(B.MON_5*1.0),4)) AS PRVYR_NOW_YR_RT_MAY ,SUM(NVL(A.MON_6,0)) AS NOW_YR_JUN ,SUM(NVL(B.MON_6,0)) AS PRVYR_JUN ,DECODE(B.MON_6,0,'0',FORMAT((A.MON_6*1.0)/(B.MON_6*1.0),4)) AS PRVYR_NOW_YR_RT_JUN ,SUM(NVL(A.MON_7,0)) AS NOW_YR_JUL ,SUM(NVL(B.MON_7,0)) AS PRVYR_JUL ,DECODE(B.MON_7,0,'0',FORMAT((A.MON_7*1.0)/(B.MON_7*1.0),4)) AS PRVYR_NOW_YR_RT_JUL ,SUM(NVL(A.MON_8,0)) AS NOW_YR_AUG ,SUM(NVL(B.MON_8,0)) AS PRVYR_AUG ,DECODE(B.MON_8,0,'0',FORMAT((A.MON_8*1.0)/(B.MON_8*1.0),4)) AS PRVYR_NOW_YR_RT_AUG ,SUM(NVL(A.MON_9,0)) AS NOW_YR_SEP ,SUM(NVL(B.MON_9,0)) AS PRVYR_SEP ,DECODE(B.MON_9,0,'0',FORMAT((A.MON_9*1.0)/(B.MON_9*1.0),4)) AS PRVYR_NOW_YR_RT_SEP ,SUM(NVL(A.MON_10,0)) AS NOW_YR_OCT ,SUM(NVL(B.MON_10,0)) AS PRVYR_OCT ,DECODE(B.MON_10,0,'0',FORMAT((A.MON_10*1.0)/(B.MON_10*1.0),4)) AS PRVYR_NOW_YR_RT_OCT ,SUM(NVL(A.MON_11,0)) AS NOW_YR_NOV ,SUM(NVL(B.MON_11,0)) AS PRVYR_NOV ,DECODE(B.MON_11,0,'0',FORMAT((A.MON_11*1.0)/(B.MON_11*1.0),4)) AS PRVYR_NOW_YR_RT_NOV ,SUM(NVL(A.MON_12,0)) AS NOW_YR_DEC ,SUM(NVL(B.MON_12,0)) AS PRVYR_DEC ,DECODE(B.MON_12,0,'0',FORMAT((A.MON_12*1.0)/(B.MON_12*1.0),4)) AS PRVYR_NOW_YR_RT_DEC FROM CURRENT_AMT A LEFT JOIN PREVIOUS_AMT B ON A.UPPER_LOCGOV_CODE = B.UPPER_LOCGOV_CODE AND A.LOCGOV_CODE = B.LOCGOV_CODE LEFT JOIN CURRENT_TOTAL C ON A.UPPER_LOCGOV_CODE = C.UPPER_LOCGOV_CODE AND A.LOCGOV_CODE = C.LOCGOV_CODE LEFT JOIN PREVIOUS_TOTAL D ON A.UPPER_LOCGOV_CODE = D.UPPER_LOCGOV_CODE AND A.LOCGOV_CODE = D.LOCGOV_CODE GROUP BY A.UPPER_LOCGOV_CODE, A.LOCGOV_CODE WITH ROLLUP ORDER BY A.UPPER_LOCGOV_CODE, A.LOCGOV_CODE

