AND B.CNTR_AMT = '20000000' WHERE 1=1 GROUP BY A.LOCGOV_CODE , A.UPPER_LOCGOV_NM, A.LOCGOV_NM ) SELECT /*+ USE_IDX(UPPER_LOCGOV_CODE) USE_MERGE(B) USE_MERGE(C) */ DECODE(NVL(A.LOCGOV_CODE, '00000'),'00000' ,DECODE(NVL(A.UPPER_LOCGOV_CODE, '00000'),'00000','총계' ,(SELECT AA.UPPER_LOCGOV_NM FROM G_LOCGOV AA WHERE AA.UPPER_LOCGOV_CODE = A.UPPER_LOCGOV_CODE GROUP BY AA.UPPER_LOCGOV_NM)),A.UPPER_LOCGOV_NM) AS UPPER_LOCGOV_NM ,NVL(A.UPPER_LOCGOV_CODE, '00000') AS UPPER_LOCGOV_CODE ,DECODE(NVL(A.LOCGOV_CODE, '00000'),'00000',DECODE(NVL(A.UPPER_LOCGOV_CODE, '00000'),'00000','','소계'),A.LOCGOV_NM) AS LOCGOV_NM ,NVL(A.LOCGOV_CODE, '00000') AS LOCGOV_CODE ,SUM(NVL(C.TOT_POINT,0)) AS NOW_YR ,SUM(NVL(D.TOT_POINT,0)) AS PRVYR ,SUM(NVL(A.MON_1,0)) AS NOW_YR_JAN ,SUM(NVL(B.MON_1,0)) AS PRVYR_JAN ,DECODE(B.MON_1,0,0,FORMAT((A.MON_1*1.0)/(B.MON_1*1.0),4)) AS PRVYR_NOW_YR_RT_JAN ,SUM(NVL(A.MON_2,0)) AS NOW_YR_FEB ,SUM(NVL(B.MON_2,0)) AS PRVYR_FEB ,DECODE(B.MON_2,0,0,FORMAT((A.MON_2*1.0)/(B.MON_2*1.0),4)) AS PRVYR_NOW_YR_RT_FEB ,SUM(NVL(A.MON_3,0)) AS NOW_YR_MAR ,SUM(NVL(B.MON_3,0)) AS PRVYR_MAR ,DECODE(B.MON_3,0,0,FORMAT((A.MON_3*1.0)/(B.MON_3*1.0),4)) AS PRVYR_NOW_YR_RT_MAR ,SUM(NVL(A.MON_4,0)) AS NOW_YR_APR ,SUM(NVL(B.MON_4,0)) AS PRVYR_APR ,DECODE(B.MON_4,0,0,FORMAT((A.MON_4*1.0)/(B.MON_4*1.0),4)) AS PRVYR_NOW_YR_RT_APR ,SUM(NVL(A.MON_5,0)) AS NOW_YR_MAY ,SUM(NVL(B.MON_5,0)) AS PRVYR_MAY ,DECODE(B.MON_5,0,0,FORMAT((A.MON_5*1.0)/(B.MON_5*1.0),4)) AS PRVYR_NOW_YR_RT_MAY ,SUM(NVL(A.MON_6,0)) AS NOW_YR_JUN ,SUM(NVL(B.MON_6,0)) AS PRVYR_JUN ,DECODE(B.MON_6,0,0,FORMAT((A.MON_6*1.0)/(B.MON_6*1.0),4)) AS PRVYR_NOW_YR_RT_JUN ,SUM(NVL(A.MON_7,0)) AS NOW_YR_JUL ,SUM(NVL(B.MON_7,0)) AS PRVYR_JUL ,DECODE(B.MON_7,0,0,FORMAT((A.MON_7*1.0)/(B.MON_7*1.0),4)) AS PRVYR_NOW_YR_RT_JUL ,SUM(NVL(A.MON_8,0)) AS NOW_YR_AUG ,SUM(NVL(B.MON_8,0)) AS PRVYR_AUG ,DECODE(B.MON_8,0,0,FORMAT((A.MON_8*1.0)/(B.MON_8*1.0),4)) AS PRVYR_NOW_YR_RT_AUG ,SUM(NVL(A.MON_9,0)) AS NOW_YR_SEP ,SUM(NVL(B.MON_9,0)) AS PRVYR_SEP ,DECODE(B.MON_9,0,0,FORMAT((A.MON_9*1.0)/(B.MON_9*1.0),4)) AS PRVYR_NOW_YR_RT_SEP ,SUM(NVL(A.MON_10,0)) AS NOW_YR_OCT ,SUM(NVL(B.MON_10,0)) AS PRVYR_OCT ,DECODE(B.MON_10,0,0,FORMAT((A.MON_10*1.0)/(B.MON_10*1.0),4)) AS PRVYR_NOW_YR_RT_OCT ,SUM(NVL(A.MON_11,0)) AS NOW_YR_NOV ,SUM(NVL(B.MON_11,0)) AS PRVYR_NOV ,DECODE(B.MON_11,0,0,FORMAT((A.MON_11*1.0)/(B.MON_11*1.0),4)) AS PRVYR_NOW_YR_RT_NOV ,SUM(NVL(A.MON_12,0)) AS NOW_YR_DEC ,SUM(NVL(B.MON_12,0)) AS PRVYR_DEC ,DECODE(B.MON_12,0,0,FORMAT((A.MON_12*1.0)/(B.MON_12*1.0),4)) AS PRVYR_NOW_YR_RT_DEC FROM CURRENT_AMT A LEFT JOIN PREVIOUS_AMT B ON A.UPPER_LOCGOV_CODE = B.UPPER_LOCGOV_CODE AND A.LOCGOV_CODE = B.LOCGOV_CODE LEFT JOIN CURRENT_TOTAL C ON A.UPPER_LOCGOV_CODE = C.UPPER_LOCGOV_CODE AND A.LOCGOV_CODE = C.LOCGOV_CODE LEFT JOIN PREVIOUS_TOTAL D ON A.UPPER_LOCGOV_CODE = D.UPPER_LOCGOV_CODE AND A.LOCGOV_CODE = D.LOCGOV_CODE GROUP BY A.UPPER_LOCGOV_CODE, A.LOCGOV_CODE WITH ROLLUP ORDER BY A.UPPER_LOCGOV_CODE, A.LOCGOV_CODE

WITH CURRENT_POINT AS ( SELECT /*+ USE_MERGE(B) */ A.UPPER_LOCGOV_NM , A.UPPER_LOCGOV_CODE , SUM(DECODE(MONTH(B.POINT_USE_DE),1,B.CNTR_USE_POINT)) AS MON_1 , SUM(DECODE(MONTH(B.POINT_USE_DE),2,B.CNTR_USE_POINT)) AS MON_2 , SUM(DECODE(MONTH(B.POINT_USE_DE),3,B.CNTR_USE_POINT)) AS MON_3 , SUM(DECODE(MONTH(B.POINT_USE_DE),4,B.CNTR_USE_POINT)) AS MON_4 , SUM(DECODE(MONTH(B.POINT_USE_DE),5,B.CNTR_USE_POINT)) AS MON_5 , SUM(DECODE(MONTH(B.POINT_USE_DE),6,B.CNTR_USE_POINT)) AS MON_6 , SUM(DECODE(MONTH(B.POINT_USE_DE),7,B.CNTR_USE_POINT)) AS MON_7 , SUM(DECODE(MONTH(B.POINT_USE_DE),8,B.CNTR_USE_POINT)) AS MON_8 , SUM(DECODE(MONTH(B.POINT_USE_DE),9,B.CNTR_USE_POINT)) AS MON_9 , SUM(DECODE(MONTH(B.POINT_USE_DE),10,B.CNTR_USE_POINT)) AS MON_10 , SUM(DECODE(MONTH(B.POINT_USE_DE),11,B.CNTR_USE_POINT)) AS MON_11 , SUM(DECODE(MONTH(B.POINT_USE_DE),12,B.CNTR_USE_POINT)) AS MON_12 FROM G_LOCGOV A LEFT JOIN ( SELECT B.CNTR_SN ,B.CNTR_LOCGOV_CODE ,A.POINT_USE_DE ,A.CNTR_USE_POINT FROM G_CNTR_USE_POINT A LEFT JOIN G_CNTR B ON A.CNTR_SN = B.CNTR_SN WHERE 1=1 AND A.USE_SE_CODE = '1' AND YEAR(A.POINT_USE_DE) = #{crtrYr}
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND '12'
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND MONTH(ADD_MONTHS(SYSDATE,-1))
) B ON A.LOCGOV_CODE = B.CNTR_LOCGOV_CODE GROUP BY A.UPPER_LOCGOV_CODE,A.UPPER_LOCGOV_NM ) , PREVIOUS_POINT AS ( SELECT /*+ USE_MERGE(B) */ A.UPPER_LOCGOV_NM , A.UPPER_LOCGOV_CODE , SUM(DECODE(MONTH(B.POINT_USE_DE),1,B.CNTR_USE_POINT)) AS MON_1 , SUM(DECODE(MONTH(B.POINT_USE_DE),2,B.CNTR_USE_POINT)) AS MON_2 , SUM(DECODE(MONTH(B.POINT_USE_DE),3,B.CNTR_USE_POINT)) AS MON_3 , SUM(DECODE(MONTH(B.POINT_USE_DE),4,B.CNTR_USE_POINT)) AS MON_4 , SUM(DECODE(MONTH(B.POINT_USE_DE),5,B.CNTR_USE_POINT)) AS MON_5 , SUM(DECODE(MONTH(B.POINT_USE_DE),6,B.CNTR_USE_POINT)) AS MON_6 , SUM(DECODE(MONTH(B.POINT_USE_DE),7,B.CNTR_USE_POINT)) AS MON_7 , SUM(DECODE(MONTH(B.POINT_USE_DE),8,B.CNTR_USE_POINT)) AS MON_8 , SUM(DECODE(MONTH(B.POINT_USE_DE),9,B.CNTR_USE_POINT)) AS MON_9 , SUM(DECODE(MONTH(B.POINT_USE_DE),10,B.CNTR_USE_POINT)) AS MON_10 , SUM(DECODE(MONTH(B.POINT_USE_DE),11,B.CNTR_USE_POINT)) AS MON_11 , SUM(DECODE(MONTH(B.POINT_USE_DE),12,B.CNTR_USE_POINT)) AS MON_12 FROM G_LOCGOV A LEFT JOIN ( SELECT B.CNTR_SN ,B.CNTR_LOCGOV_CODE ,A.POINT_USE_DE ,A.CNTR_USE_POINT FROM G_CNTR_USE_POINT A LEFT JOIN G_CNTR B ON A.CNTR_SN = B.CNTR_SN WHERE 1=1 AND A.USE_SE_CODE = '1' AND YEAR(A.POINT_USE_DE) = #{paramPrvYr}
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND '12'
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND MONTH(ADD_MONTHS(SYSDATE,-1))
) B ON A.LOCGOV_CODE = B.CNTR_LOCGOV_CODE GROUP BY A.UPPER_LOCGOV_CODE,A.UPPER_LOCGOV_NM ) select UPPER_LOCGOV_NM ,UPPER_LOCGOV_CODE ,NOW_YR_JAN ,PRVYR_JAN ,DECODE(PRVYR_JAN,0,0,FORMAT((NOW_YR_JAN*1.0)/(PRVYR_JAN*1.0),4)) AS PRVYR_NOW_YR_RT_JAN ,NOW_YR_FEB ,PRVYR_FEB ,DECODE(PRVYR_FEB,0,0,FORMAT((NOW_YR_FEB*1.0)/(PRVYR_FEB*1.0),4)) AS PRVYR_NOW_YR_RT_FEB ,NOW_YR_MAR ,PRVYR_MAR ,DECODE(PRVYR_MAR,0,0,FORMAT((NOW_YR_MAR*1.0)/(PRVYR_MAR*1.0),4)) AS PRVYR_NOW_YR_RT_MAR ,NOW_YR_APR ,PRVYR_APR ,DECODE(PRVYR_APR,0,0,FORMAT((NOW_YR_APR*1.0)/(PRVYR_APR*1.0),4)) AS PRVYR_NOW_YR_RT_APR ,NOW_YR_MAY ,PRVYR_MAY ,DECODE(PRVYR_MAY,0,0,FORMAT((NOW_YR_MAY*1.0)/(PRVYR_MAY*1.0),4)) AS PRVYR_NOW_YR_RT_MAY ,NOW_YR_JUN ,PRVYR_JUN ,DECODE(PRVYR_JUN,0,0,FORMAT((NOW_YR_JUN*1.0)/(PRVYR_JUN*1.0),4)) AS PRVYR_NOW_YR_RT_JUN ,NOW_YR_JUL ,PRVYR_JUL ,DECODE(PRVYR_JUL,0,0,FORMAT((NOW_YR_JUL*1.0)/(PRVYR_JUL*1.0),4)) AS PRVYR_NOW_YR_RT_JUL ,NOW_YR_AUG ,PRVYR_AUG ,DECODE(PRVYR_AUG,0,0,FORMAT((NOW_YR_AUG*1.0)/(PRVYR_AUG*1.0),4)) AS PRVYR_NOW_YR_RT_AUG ,NOW_YR_SEP ,PRVYR_SEP ,DECODE(PRVYR_SEP,0,0,FORMAT((NOW_YR_SEP*1.0)/(PRVYR_SEP*1.0),4)) AS PRVYR_NOW_YR_RT_SEP ,NOW_YR_OCT ,PRVYR_OCT ,DECODE(PRVYR_OCT,0,0,FORMAT((NOW_YR_OCT*1.0)/(PRVYR_OCT*1.0),4)) as PRVYR_NOW_YR_RT_OCT ,NOW_YR_NOV ,PRVYR_NOV ,DECODE(PRVYR_NOV,0,0,FORMAT((NOW_YR_NOV*1.0)/(PRVYR_NOV*1.0),4)) as PRVYR_NOW_YR_RT_NOV ,NOW_YR_DEC ,PRVYR_DEC ,DECODE(PRVYR_DEC,0,0,FORMAT((NOW_YR_DEC*1.0)/(PRVYR_DEC*1.0),4)) as PRVYR_NOW_YR_RT_DEC from ( select UPPER_LOCGOV_NM ,UPPER_LOCGOV_CODE ,NOW_YR_JAN as NOW_YR_JAN ,PRVYR_JAN as PRVYR_JAN ,NOW_YR_FEB + NOW_YR_JAN as NOW_YR_FEB ,PRVYR_FEB + PRVYR_JAN as PRVYR_FEB ,NOW_YR_MAR + NOW_YR_FEB + NOW_YR_JAN as NOW_YR_MAR ,PRVYR_MAR + PRVYR_FEB + PRVYR_JAN as PRVYR_MAR ,NOW_YR_APR + NOW_YR_MAR + NOW_YR_FEB + NOW_YR_JAN as NOW_YR_APR ,PRVYR_APR + PRVYR_MAR + PRVYR_FEB + PRVYR_JAN as PRVYR_APR ,NOW_YR_MAY + NOW_YR_APR + NOW_YR_MAR + NOW_YR_FEB + NOW_YR_JAN as NOW_YR_MAY ,PRVYR_MAY + PRVYR_APR + PRVYR_MAR + PRVYR_FEB + PRVYR_JAN as PRVYR_MAY ,NOW_YR_JUN + NOW_YR_MAY + NOW_YR_APR + NOW_YR_MAR + NOW_YR_FEB + NOW_YR_JAN as NOW_YR_JUN ,PRVYR_JUN + PRVYR_MAY + PRVYR_APR + PRVYR_MAR + PRVYR_FEB + PRVYR_JAN as PRVYR_JUN ,NOW_YR_JUL + NOW_YR_JUN + NOW_YR_MAY + NOW_YR_APR + NOW_YR_MAR + NOW_YR_FEB + NOW_YR_JAN as NOW_YR_JUL ,PRVYR_JUL + PRVYR_JUN + PRVYR_MAY + PRVYR_APR + PRVYR_MAR + PRVYR_FEB + PRVYR_JAN as PRVYR_JUL ,NOW_YR_AUG + NOW_YR_JUL + NOW_YR_JUN + NOW_YR_MAY + NOW_YR_APR + NOW_YR_MAR + NOW_YR_FEB + NOW_YR_JAN as NOW_YR_AUG ,PRVYR_AUG + PRVYR_JUL + PRVYR_JUN + PRVYR_MAY + PRVYR_APR + PRVYR_MAR + PRVYR_FEB + PRVYR_JAN as PRVYR_AUG ,NOW_YR_SEP + NOW_YR_AUG + NOW_YR_JUL + NOW_YR_JUN + NOW_YR_MAY + NOW_YR_APR + NOW_YR_MAR + NOW_YR_FEB + NOW_YR_JAN as NOW_YR_SEP ,PRVYR_SEP + PRVYR_AUG + PRVYR_JUL + PRVYR_JUN + PRVYR_MAY + PRVYR_APR + PRVYR_MAR + PRVYR_FEB + PRVYR_JAN as PRVYR_SEP ,NOW_YR_OCT + NOW_YR_SEP + NOW_YR_AUG + NOW_YR_JUL + NOW_YR_JUN + NOW_YR_MAY + NOW_YR_APR + NOW_YR_MAR + NOW_YR_FEB + NOW_YR_JAN as NOW_YR_OCT ,PRVYR_OCT + PRVYR_SEP + PRVYR_AUG + PRVYR_JUL + PRVYR_JUN + PRVYR_MAY + PRVYR_APR + PRVYR_MAR + PRVYR_FEB + PRVYR_JAN as PRVYR_OCT ,NOW_YR_NOV + NOW_YR_OCT + NOW_YR_SEP + NOW_YR_AUG + NOW_YR_JUL + NOW_YR_JUN + NOW_YR_MAY + NOW_YR_APR + NOW_YR_MAR + NOW_YR_FEB + NOW_YR_JAN as NOW_YR_NOV ,PRVYR_NOV + PRVYR_OCT + PRVYR_SEP + PRVYR_AUG + PRVYR_JUL + PRVYR_JUN + PRVYR_MAY + PRVYR_APR + PRVYR_MAR + PRVYR_FEB + PRVYR_JAN as PRVYR_NOV ,NOW_YR_DEC + NOW_YR_NOV + NOW_YR_OCT + NOW_YR_SEP + NOW_YR_AUG + NOW_YR_JUL + NOW_YR_JUN + NOW_YR_MAY + NOW_YR_APR + NOW_YR_MAR + NOW_YR_FEB + NOW_YR_JAN as NOW_YR_DEC ,PRVYR_DEC + PRVYR_NOV + PRVYR_OCT + PRVYR_SEP + PRVYR_AUG + PRVYR_JUL + PRVYR_JUN + PRVYR_MAY + PRVYR_APR + PRVYR_MAR + PRVYR_FEB + PRVYR_JAN as PRVYR_DEC from ( SELECT /*+ USE_MERGE(B) */ NVL(A.UPPER_LOCGOV_NM,'총계') as UPPER_LOCGOV_NM ,NVL(A.UPPER_LOCGOV_CODE, '00000') AS UPPER_LOCGOV_CODE ,SUM(NVL(A.MON_1,0)) AS NOW_YR_JAN ,SUM(NVL(B.MON_1,0)) AS PRVYR_JAN ,SUM(NVL(A.MON_2,0)) AS NOW_YR_FEB ,SUM(NVL(B.MON_2,0)) AS PRVYR_FEB ,SUM(NVL(A.MON_3,0)) AS NOW_YR_MAR ,SUM(NVL(B.MON_3,0)) AS PRVYR_MAR ,SUM(NVL(A.MON_4,0)) AS NOW_YR_APR ,SUM(NVL(B.MON_4,0)) AS PRVYR_APR ,SUM(NVL(A.MON_5,0)) AS NOW_YR_MAY ,SUM(NVL(B.MON_5,0)) AS PRVYR_MAY ,SUM(NVL(A.MON_6,0)) AS NOW_YR_JUN ,SUM(NVL(B.MON_6,0)) AS PRVYR_JUN ,SUM(NVL(A.MON_7,0)) AS NOW_YR_JUL ,SUM(NVL(B.MON_7,0)) AS PRVYR_JUL ,SUM(NVL(A.MON_8,0)) AS NOW_YR_AUG ,SUM(NVL(B.MON_8,0)) AS PRVYR_AUG ,SUM(NVL(A.MON_9,0)) AS NOW_YR_SEP ,SUM(NVL(B.MON_9,0)) AS PRVYR_SEP ,SUM(NVL(A.MON_10,0)) AS NOW_YR_OCT ,SUM(NVL(B.MON_10,0)) AS PRVYR_OCT ,SUM(NVL(A.MON_11,0)) AS NOW_YR_NOV ,SUM(NVL(B.MON_11,0)) AS PRVYR_NOV ,SUM(NVL(A.MON_12,0)) AS NOW_YR_DEC ,SUM(NVL(B.MON_12,0)) AS PRVYR_DEC FROM CURRENT_POINT A LEFT JOIN PREVIOUS_POINT B ON A.UPPER_LOCGOV_CODE = B.UPPER_LOCGOV_CODE GROUP BY A.UPPER_LOCGOV_CODE WITH ROLLUP ORDER BY A.UPPER_LOCGOV_CODE ) )

WITH CURRENT_POINT AS ( SELECT /*+ USE_MERGE(B) */ A.UPPER_LOCGOV_NM , A.UPPER_LOCGOV_CODE , A.LOCGOV_CODE , A.LOCGOV_NM , SUM(DECODE(MONTH(B.POINT_USE_DE),1,B.CNTR_USE_POINT)) AS MON_1 , SUM(DECODE(MONTH(B.POINT_USE_DE),2,B.CNTR_USE_POINT)) AS MON_2 , SUM(DECODE(MONTH(B.POINT_USE_DE),3,B.CNTR_USE_POINT)) AS MON_3 , SUM(DECODE(MONTH(B.POINT_USE_DE),4,B.CNTR_USE_POINT)) AS MON_4 , SUM(DECODE(MONTH(B.POINT_USE_DE),5,B.CNTR_USE_POINT)) AS MON_5 , SUM(DECODE(MONTH(B.POINT_USE_DE),6,B.CNTR_USE_POINT)) AS MON_6 , SUM(DECODE(MONTH(B.POINT_USE_DE),7,B.CNTR_USE_POINT)) AS MON_7 , SUM(DECODE(MONTH(B.POINT_USE_DE),8,B.CNTR_USE_POINT)) AS MON_8 , SUM(DECODE(MONTH(B.POINT_USE_DE),9,B.CNTR_USE_POINT)) AS MON_9 , SUM(DECODE(MONTH(B.POINT_USE_DE),10,B.CNTR_USE_POINT)) AS MON_10 , SUM(DECODE(MONTH(B.POINT_USE_DE),11,B.CNTR_USE_POINT)) AS MON_11 , SUM(DECODE(MONTH(B.POINT_USE_DE),12,B.CNTR_USE_POINT)) AS MON_12 FROM G_LOCGOV A LEFT JOIN ( SELECT B.CNTR_SN ,B.CNTR_LOCGOV_CODE ,A.POINT_USE_DE ,A.CNTR_USE_POINT FROM G_CNTR_USE_POINT A LEFT JOIN G_CNTR B ON A.CNTR_SN = B.CNTR_SN WHERE 1=1 AND A.USE_SE_CODE = '1' AND YEAR(A.POINT_USE_DE) = #{crtrYr}
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND '12'
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND MONTH(ADD_MONTHS(SYSDATE,-1))
) B ON A.LOCGOV_CODE = B.CNTR_LOCGOV_CODE GROUP BY A.LOCGOV_CODE , A.UPPER_LOCGOV_NM, A.LOCGOV_NM ) ,CURRENT_TOTAL AS ( SELECT /*+ USE_MERGE(B) */ A.UPPER_LOCGOV_NM , A.UPPER_LOCGOV_CODE , A.LOCGOV_CODE , A.LOCGOV_NM , SUM(B.CNTR_USE_POINT) AS TOT_POINT FROM G_LOCGOV A LEFT JOIN ( SELECT B.CNTR_SN ,B.CNTR_LOCGOV_CODE ,A.POINT_USE_DE ,A.CNTR_USE_POINT FROM G_CNTR_USE_POINT A LEFT JOIN G_CNTR B ON A.CNTR_SN = B.CNTR_SN WHERE 1=1 AND A.USE_SE_CODE = '1' AND YEAR(A.POINT_USE_DE) = #{crtrYr}
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND '12'
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND MONTH(ADD_MONTHS(SYSDATE,-1))
) B ON A.LOCGOV_CODE = B.CNTR_LOCGOV_CODE where B.CNTR_LOCGOV_CODE is not NULL GROUP BY A.LOCGOV_CODE , A.UPPER_LOCGOV_NM, A.LOCGOV_NM ) , PREVIOUS_POINT AS ( SELECT /*+ USE_MERGE(B) */ A.UPPER_LOCGOV_NM , A.UPPER_LOCGOV_CODE , A.LOCGOV_CODE , A.LOCGOV_NM , SUM(DECODE(MONTH(B.POINT_USE_DE),1,B.CNTR_USE_POINT)) AS MON_1 , SUM(DECODE(MONTH(B.POINT_USE_DE),2,B.CNTR_USE_POINT)) AS MON_2 , SUM(DECODE(MONTH(B.POINT_USE_DE),3,B.CNTR_USE_POINT)) AS MON_3 , SUM(DECODE(MONTH(B.POINT_USE_DE),4,B.CNTR_USE_POINT)) AS MON_4 , SUM(DECODE(MONTH(B.POINT_USE_DE),5,B.CNTR_USE_POINT)) AS MON_5 , SUM(DECODE(MONTH(B.POINT_USE_DE),6,B.CNTR_USE_POINT)) AS MON_6 , SUM(DECODE(MONTH(B.POINT_USE_DE),7,B.CNTR_USE_POINT)) AS MON_7 , SUM(DECODE(MONTH(B.POINT_USE_DE),8,B.CNTR_USE_POINT)) AS MON_8 , SUM(DECODE(MONTH(B.POINT_USE_DE),9,B.CNTR_USE_POINT)) AS MON_9 , SUM(DECODE(MONTH(B.POINT_USE_DE),10,B.CNTR_USE_POINT)) AS MON_10 , SUM(DECODE(MONTH(B.POINT_USE_DE),11,B.CNTR_USE_POINT)) AS MON_11 , SUM(DECODE(MONTH(B.POINT_USE_DE),12,B.CNTR_USE_POINT)) AS MON_12 FROM G_LOCGOV A LEFT JOIN ( SELECT B.CNTR_SN ,B.CNTR_LOCGOV_CODE ,A.POINT_USE_DE ,A.CNTR_USE_POINT FROM G_CNTR_USE_POINT A LEFT JOIN G_CNTR B ON A.CNTR_SN = B.CNTR_SN WHERE 1=1 AND A.USE_SE_CODE = '1' AND YEAR(A.POINT_USE_DE) = #{paramPrvYr}
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND '12'
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND MONTH(ADD_MONTHS(SYSDATE,-1))
) B ON A.LOCGOV_CODE = B.CNTR_LOCGOV_CODE where B.CNTR_LOCGOV_CODE is not NULL GROUP BY A.LOCGOV_CODE , A.UPPER_LOCGOV_NM, A.LOCGOV_NM ) ,PREVIOUS_TOTAL AS ( SELECT /*+ USE_MERGE(B) */ A.UPPER_LOCGOV_NM , A.UPPER_LOCGOV_CODE , A.LOCGOV_CODE , A.LOCGOV_NM , SUM(B.CNTR_USE_POINT) AS TOT_POINT FROM G_LOCGOV A LEFT JOIN ( SELECT B.CNTR_SN ,B.CNTR_LOCGOV_CODE ,A.POINT_USE_DE ,A.CNTR_USE_POINT FROM G_CNTR_USE_POINT A LEFT JOIN G_CNTR B ON A.CNTR_SN = B.CNTR_SN WHERE 1=1 AND A.USE_SE_CODE = '1' AND YEAR(A.POINT_USE_DE) = #{paramPrvYr}
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND '12'
AND MONTH(A.POINT_USE_DE) BETWEEN '1' AND MONTH(ADD_MONTHS(SYSDATE,-1))
) B ON A.LOCGOV_CODE = B.CNTR_LOCGOV_CODE where B.CNTR_LOCGOV_CODE is not NULL GROUP BY A.LOCGOV_CODE , A.UPPER_LOCGOV_NM, A.LOCGOV_NM ) SELECT /*+ USE_IDX(UPPER_LOCGOV_CODE) USE_MERGE(B) USE_MERGE(C) */ DECODE(NVL(A.LOCGOV_CODE, '00000'),'00000' ,DECODE(NVL(A.UPPER_LOCGOV_CODE, '00000'),'00000','총계' ,(SELECT AA.UPPER_LOCGOV_NM FROM G_LOCGOV AA WHERE AA.UPPER_LOCGOV_CODE = A.UPPER_LOCGOV_CODE GROUP BY AA.UPPER_LOCGOV_NM)),A.UPPER_LOCGOV_NM) AS UPPER_LOCGOV_NM ,DECODE(NVL(A.LOCGOV_CODE, '00000'),'00000',DECODE(NVL(A.UPPER_LOCGOV_CODE, '00000'),'00000','','소계'),A.LOCGOV_NM) AS LOCGOV_NM ,NVL(A.UPPER_LOCGOV_CODE, '00000') AS UPPER_LOCGOV_CODE ,NVL(A.LOCGOV_CODE, '00000') AS LOCGOV_CODE ,SUM(NVL(C.TOT_POINT,0)) AS NOW_YR ,SUM(NVL(D.TOT_POINT,0)) AS PRVYR ,SUM(NVL(A.MON_1,0)) AS NOW_YR_JAN ,SUM(NVL(B.MON_1,0)) AS PRVYR_JAN ,DECODE(B.MON_1,0,0,FORMAT((A.MON_1*1.0)/(B.MON_1*1.0),4)) AS PRVYR_NOW_YR_RT_JAN ,SUM(NVL(A.MON_2,0)) AS NOW_YR_FEB ,SUM(NVL(B.MON_2,0)) AS PRVYR_FEB ,DECODE(B.MON_2,0,0,FORMAT((A.MON_2*1.0)/(B.MON_2*1.0),4)) AS PRVYR_NOW_YR_RT_FEB ,SUM(NVL(A.MON_3,0)) AS NOW_YR_MAR ,SUM(NVL(B.MON_3,0)) AS PRVYR_MAR ,DECODE(B.MON_3,0,0,FORMAT((A.MON_3*1.0)/(B.MON_3*1.0),4)) AS PRVYR_NOW_YR_RT_MAR ,SUM(NVL(A.MON_4,0)) AS NOW_YR_APR ,SUM(NVL(B.MON_4,0)) AS PRVYR_APR ,DECODE(B.MON_4,0,0,FORMAT((A.MON_4*1.0)/(B.MON_4*1.0),4)) AS PRVYR_NOW_YR_RT_APR ,SUM(NVL(A.MON_5,0)) AS NOW_YR_MAY ,SUM(NVL(B.MON_5,0)) AS PRVYR_MAY ,DECODE(B.MON_5,0,0,FORMAT((A.MON_5*1.0)/(B.MON_5*1.0),4)) AS PRVYR_NOW_YR_RT_MAY ,SUM(NVL(A.MON_6,0)) AS NOW_YR_JUN ,SUM(NVL(B.MON_6,0)) AS PRVYR_JUN ,DECODE(B.MON_6,0,0,FORMAT((A.MON_6*1.0)/(B.MON_6*1.0),4)) AS PRVYR_NOW_YR_RT_JUN ,SUM(NVL(A.MON_7,0)) AS NOW_YR_JUL ,SUM(NVL(B.MON_7,0)) AS PRVYR_JUL ,DECODE(B.MON_7,0,0,FORMAT((A.MON_7*1.0)/(B.MON_7*1.0),4)) AS PRVYR_NOW_YR_RT_JUL ,SUM(NVL(A.MON_8,0)) AS NOW_YR_AUG ,SUM(NVL(B.MON_8,0)) AS PRVYR_AUG ,DECODE(B.MON_8,0,0,FORMAT((A.MON_8*1.0)/(B.MON_8*1.0),4)) AS PRVYR_NOW_YR_RT_AUG ,SUM(NVL(A.MON_9,0)) AS NOW_YR_SEP ,SUM(NVL(B.MON_9,0)) AS PRVYR_SEP ,DECODE(B.MON_9,0,0,FORMAT((A.MON_9*1.0)/(B.MON_9*1.0),4)) AS PRVYR_NOW_YR_RT_SEP ,SUM(NVL(A.MON_10,0)) AS NOW_YR_OCT ,SUM(NVL(B.MON_10,0)) AS PRVYR_OCT ,DECODE(B.MON_10,0,0,FORMAT((A.MON_10*1.0)/(B.MON_10*1.0),4)) AS PRVYR_NOW_YR_RT_OCT ,SUM(NVL(A.MON_11,0)) AS NOW_YR_NOV ,SUM(NVL(B.MON_11,0)) AS PRVYR_NOV ,DECODE(B.MON_11,0,0,FORMAT((A.MON_11*1.0)/(B.MON_11*1.0),4)) AS PRVYR_NOW_YR_RT_NOV ,SUM(NVL(A.MON_12,0)) AS NOW_YR_DEC ,SUM(NVL(B.MON_12,0)) AS PRVYR_DEC ,DECODE(B.MON_12,0,0,FORMAT((A.MON_12*1.0)/(B.MON_12*1.0),4)) AS PRVYR_NOW_YR_RT_DEC FROM CURRENT_POINT A LEFT JOIN PREVIOUS_POINT B ON A.UPPER_LOCGOV_CODE = B.UPPER_LOCGOV_CODE AND A.LOCGOV_CODE = B.LOCGOV_CODE LEFT JOIN CURRENT_TOTAL C ON A.UPPER_LOCGOV_CODE = C.UPPER_LOCGOV_CODE AND A.LOCGOV_CODE = C.LOCGOV_CODE LEFT JOIN PREVIOUS_TOTAL D ON A.UPPER_LOCGOV_CODE = D.UPPER_LOCGOV_CODE AND A.LOCGOV_CODE = D.LOCGOV_CODE GROUP BY A.UPPER_LOCGOV_CODE, A.LOCGOV_CODE WITH ROLLUP ORDER BY A.UPPER_LOCGOV_CODE, A.LOCGOV_CODE

/* saleson.shop.slave.SlaveShopStatisticsMapper.getNhItemSalesStats 농협 사업자 답례품 현황 */
SELECT BUSINESS_NUMBER , LOGIN_ID , COMPANY_NAME , UPPER_LOCGOV_NM , LOCGOV_NM , ITEM_NAME , C_GROUP_NAME AS CATEGORY_NMS , CATE_NAME AS CATEGORY_DETAIL_NMS , SALE_PRICE AS PRICE , SUM(ORDER_CNT) AS ORDER_CNT , SUM(QUANTITY) AS SALE_CNT , SUM(PRICE) AS TOTAL_SALE_PRICE , ITEM_USER_CODE FROM ( SELECT T_B.ITEM_ID , T_B.BUSINESS_NUMBER , T_B.LOGIN_ID , T_B.COMPANY_NAME , T_B.UPPER_LOCGOV_NM , T_B.LOCGOV_NM , T_B.LOCGOV_CODE , T_B.ITEM_NAME , T_B.C_GROUP_NAME , T_B.CATE_NAME , T_B.SALE_PRICE , T_B.SELLER_ID , IFNULL((OI.SALE_PRICE * OI.QUANTITY + OI.ETC_AMT), 0) AS PRICE , IFNULL(OI.QUANTITY, 0) AS QUANTITY , CASE WHEN OI.ORDER_CODE IS NOT NULL AND OI.ORDER_CODE != '' THEN 1 ELSE 0 END ORDER_CNT , T_B.ITEM_USER_CODE FROM ( SELECT T_A.ITEM_ID , S.LOGIN_ID , T_A.CATEGORY_ID , T_A.ITEM_NAME , T_A.SALE_PRICE , T_A.SELLER_ID , L.LOCGOV_CODE , L.UPPER_LOCGOV_NM || ' ' || L.LOCGOV_NM AS FULL_LOCGOV_NM , L.UPPER_LOCGOV_NM , L.LOCGOV_NM , GROUP_CONCAT(DISTINCT CG.NAME SEPARATOR ' , ') AS C_GROUP_NAME , GROUP_CONCAT(DISTINCT C.CATEGORY_NAME SEPARATOR ' , ') AS CATE_NAME , S.BUSINESS_NUMBER , S.COMPANY_NAME , T_A.ITEM_USER_CODE FROM ( SELECT I.ITEM_ID , IC.CATEGORY_ID , I.ITEM_NAME , I.SALE_PRICE , I.SELLER_ID , I.ITEM_USER_CODE FROM OP_ITEM I LEFT JOIN OP_ITEM_CATEGORY IC ON I.ITEM_ID = IC.ITEM_ID WHERE 1=1
AND I.ITEM_NAME LIKE CONCAT('%', #{query}, '%')
) T_A LEFT JOIN OP_CATEGORY C ON T_A.CATEGORY_ID = C.CATEGORY_ID LEFT JOIN OP_CATEGORY_GROUP CG ON C.CATEGORY_GROUP_ID = CG.CATEGORY_GROUP_ID JOIN OP_SELLER S ON T_A.SELLER_ID = S.SELLER_ID JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE JOIN G_NH_STAT_DATA_TEMP NSDT ON S.BUSINESS_NUMBER = NSDT.BUSINESS_NO WHERE 1 = 1
AND L.UPPER_LOCGOV_CODE = #{upperLocgovCode}
AND L.LOCGOV_CODE = #{locgovCode}
AND S.BUSINESS_NUMBER LIKE CONCAT('%', #{query}, '%')
AND S.LOGIN_ID LIKE CONCAT('%', #{query}, '%')
AND S.COMPANY_NAME LIKE CONCAT('%', #{query}, '%')
GROUP BY T_A.ITEM_ID ) T_B LEFT JOIN OP_ORDER_ITEM OI ON T_B.ITEM_ID = OI.ITEM_ID AND OI.ORDER_STATUS = '40' AND YEAR(OI.PAY_DATE) = #{searchYear} AND MONTH(OI.PAY_DATE) = #{searchMonth} WHERE 1 = 1 ) T_C GROUP BY T_C.ITEM_ID ORDER BY T_C.BUSINESS_NUMBER, T_C.LOCGOV_CODE, T_C.SELLER_ID

/* saleson.shop.slave.SlaveShopStatisticsMapper.getNhItemSalesStatsCount 농협 사업자 답례품 현황 목록수 */ SELECT COUNT(*) FROM ( SELECT BUSINESS_NUMBER , LOGIN_ID , COMPANY_NAME , UPPER_LOCGOV_NM , LOCGOV_NM , ITEM_NAME , C_GROUP_NAME AS CATEGORY_NMS , CATE_NAME AS CATEGORY_DETAIL_NMS , SALE_PRICE AS PRICE , SUM(ORDER_CNT) AS ORDER_CNT , SUM(QUANTITY) AS SALE_CNT , SUM(PRICE) AS TOTAL_SALE_PRICE , ITEM_USER_CODE FROM ( SELECT T_B.ITEM_ID , T_B.BUSINESS_NUMBER , T_B.LOGIN_ID , T_B.COMPANY_NAME , T_B.UPPER_LOCGOV_NM , T_B.LOCGOV_NM , T_B.LOCGOV_CODE , T_B.ITEM_NAME , T_B.C_GROUP_NAME , T_B.CATE_NAME , T_B.SALE_PRICE , T_B.SELLER_ID , IFNULL((OI.SALE_PRICE * OI.QUANTITY + OI.ETC_AMT), 0) AS PRICE , IFNULL(OI.QUANTITY, 0) AS QUANTITY , CASE WHEN OI.ORDER_CODE IS NOT NULL AND OI.ORDER_CODE != '' THEN 1 ELSE 0 END ORDER_CNT , T_B.ITEM_USER_CODE FROM ( SELECT T_A.ITEM_ID , S.LOGIN_ID , T_A.CATEGORY_ID , T_A.ITEM_NAME , T_A.SALE_PRICE , T_A.SELLER_ID , L.LOCGOV_CODE , L.UPPER_LOCGOV_NM || ' ' || L.LOCGOV_NM AS FULL_LOCGOV_NM , L.UPPER_LOCGOV_NM , L.LOCGOV_NM , GROUP_CONCAT(DISTINCT CG.NAME SEPARATOR ' , ') AS C_GROUP_NAME , GROUP_CONCAT(DISTINCT C.CATEGORY_NAME SEPARATOR ' , ') AS CATE_NAME , S.BUSINESS_NUMBER , S.COMPANY_NAME , T_A.ITEM_USER_CODE FROM ( SELECT I.ITEM_ID , IC.CATEGORY_ID , I.ITEM_NAME , I.SALE_PRICE , I.SELLER_ID , I.ITEM_USER_CODE FROM OP_ITEM I LEFT JOIN OP_ITEM_CATEGORY IC ON I.ITEM_ID = IC.ITEM_ID WHERE 1=1
AND I.ITEM_NAME LIKE CONCAT('%', #{query}, '%')
) T_A LEFT JOIN OP_CATEGORY C ON T_A.CATEGORY_ID = C.CATEGORY_ID LEFT JOIN OP_CATEGORY_GROUP CG ON C.CATEGORY_GROUP_ID = CG.CATEGORY_GROUP_ID JOIN OP_SELLER S ON T_A.SELLER_ID = S.SELLER_ID JOIN G_LOCGOV L ON S.LOCGOV_CODE = L.LOCGOV_CODE JOIN G_NH_STAT_DATA_TEMP NSDT ON S.BUSINESS_NUMBER = NSDT.BUSINESS_NO WHERE 1 = 1
AND L.UPPER_LOCGOV_CODE = #{upperLocgovCode}
AND L.LOCGOV_CODE = #{locgovCode}
AND S.BUSINESS_NUMBER LIKE CONCAT('%', #{query}, '%')
AND S.LOGIN_ID LIKE CONCAT('%', #{query}, '%')
AND S.COMPANY_NAME LIKE CONCAT('%', #{query}, '%')
GROUP BY T_A.ITEM_ID ) T_B LEFT JOIN OP_ORDER_ITEM OI ON T_B.ITEM_ID = OI.ITEM_ID AND OI.ORDER_STATUS = '40' AND YEAR(OI.PAY_DATE) = #{searchYear} AND MONTH(OI.PAY_DATE) = #{searchMonth} WHERE 1 = 1 ) T_C GROUP BY T_C.ITEM_ID ORDER BY T_C.BUSINESS_NUMBER, T_C.LOCGOV_CODE, T_C.SELLER_ID )

with categories as ( select '10만원 미만' as gramt, 1 as od union all select '10만원' as gramt, 2 as od union all select '10~100만원 미만' as gramt, 3 as od union all select '100~500만원 미만' as gramt, 4 as od union all select '500만원' as gramt, 5 as od union all select '500~2000만원 미만' as gramt, 6 as od union all select '2000만원' as gramt, 7 as od ), donation_data as ( SELECT CASE WHEN CNTR_AMT < '100000' THEN '10만원 미만' WHEN CNTR_AMT = '100000' THEN '10만원' WHEN CNTR_AMT < '1000000' THEN '10~100만원 미만' WHEN CNTR_AMT < '5000000' THEN '100~500만원 미만' WHEN CNTR_AMT = '5000000' THEN '500만원' WHEN CNTR_AMT < '20000000' THEN '500~2000만원 미만' WHEN CNTR_AMT = '20000000' THEN '2000만원' END AS GRAMT, count(1) as tnocs, sum(cntr_amt) as atm from G_CNTR where 1=1 and YEAR(CNTR_DE) = #{crtrYr}
AND CNTR_LOCGOV_CODE = #{locgovCode}
AND MONTH(CNTR_DE) BETWEEN '1' AND '12' AND CNTR_STTUS_CODE = '200' group by case WHEN CNTR_AMT < '100000' THEN '10만원 미만' WHEN CNTR_AMT = '100000' THEN '10만원' WHEN CNTR_AMT < '1000000' THEN '10~100만원 미만' WHEN CNTR_AMT < '5000000' THEN '100~500만원 미만' WHEN CNTR_AMT = '5000000' THEN '500만원' WHEN CNTR_AMT < '20000000' THEN '500~2000만원 미만' WHEN CNTR_AMT = '20000000' THEN '2000만원' end ) select c.gramt as GRAMT, nvl(D.tnocs, 0) as TNOCS, nvl(D.atm, 0) as ATM, round(nvl(d.atm, 0),-6) / 1000000 as ATMHUND, OD from categories c left join donation_data d on c.gramt = d.gramt union all select '합계' as GRAMT, sum(tnocs) as TNOCS, sum(atm) as ATM, round(sum(atm),-6) / 1000000 as ATMHUND, 99 as OD from donation_data order by OD
